insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Banana and the Lesson of Kindness', 'banana-lesson-kindness', 'little_stars', '3-5', 'daily_life', 'Hadith: Abu Huraira reported, the Prophet said, ''Every joint of a person must perform a charity every day...kindness is charity''', 'Sahih Bukhari 973 - Acts of kindness as charity', 'kindness', 'Amira brings a banana to share, not knowing it will turn her ordinary day into something extraordinary and teach her about the joy of giving.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Amira woke up with a smile. Today felt special. She picked a yellow banana from the fruit basket.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-01.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Holding her banana, Amira danced to the window. She saw birds flying under the blue sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-02.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Mama said, ''Be kind, Amira. Kindness is like sunshine for the heart.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-03.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Amira decided to share her banana with her friend, Samir, at the park.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-04.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'At the park, Amira and Samir sat under a big, green tree. Amira shared her banana.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-05.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, '''Thank you, Amira!'' said Samir. ''This is the best banana ever!''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-06.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'They laughed and played, running with the wind, as the sun began to set.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-07.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'A little bird chirped happily from a nearby branch, joining their joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-08.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'On her way home, Amira remembered Mama''s words about kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-09.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'She felt her heart glowing like a warm, golden light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-10.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'At home, Amira told Mama about her day. Mama smiled and hugged her tightly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-11.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, '''You shared your banana. That is a wonderful act of kindness, my dear,'' said Mama.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-12.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Amira felt like the happiest girl in the world as she prepared for bed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-13.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'She whispered a prayer, thanking Allah for a beautiful day.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-14.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'As Amira drifted to sleep, stars twinkled gently outside her window.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-15.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Goodnight, sweet Amira. May your dreams be filled with kindness and joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/banana-lesson-kindness/page-16.webp' from public.stories where slug='banana-lesson-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Bird''s Trust', 'bird-trust', 'rising_moons', '6-8', 'quran_inspired', 'Quran 67:19', 'Do they not see the birds held up in the sky?', 'trust_in_allah', 'A young bird learns to fly by watching how Allah sustains all creatures. A beautiful story about faith and letting go.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a lush, green forest, a little bird named Noura sat high in her nest. Her heart fluttered with excitement and a hint of fear as she watched her siblings take flight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-01.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Mama Bird perched beside her, whispering softly, "Trust in Allah, dear Noura. Just as He holds the sky, He will hold you." Noura listened carefully, her heart filling with warmth.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-02.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'As the sun began to set, painting the sky in warm oranges and pinks, Noura felt a new courage within her. She spread her wings and took a deep breath.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-03.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'With Mama Bird’s words in her heart, Noura leapt from the nest. For a moment, the world seemed to hold its breath as she soared through the sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-04.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Fear turned to joy as she felt the air beneath her wings. "This is amazing!" she chirped, feeling lighter than a feather.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-05.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As night fell, Noura returned to her nest, her heart full of gratitude. She nestled close to her family, feeling the gentle embrace of Allah’s love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-06.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, '"Thank you, Mama," she whispered, "for teaching me to trust." Mama Bird smiled, "You have always had wings, my dear. You just needed to believe."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-07.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Noura closed her eyes, dreaming of new heights and adventures, knowing that she would never fly alone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-08.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'She dreamt of clouds and stars, and how each one was a reminder of Allah’s protection.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-09.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'As she drifted deeper into sleep, Noura knew that trusting in Allah would always guide her flights.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bird-trust/page-10.webp' from public.stories where slug='bird-trust' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Boy Who Shared His Last Date', 'boy-shared-last-date', 'little_stars', '3-5', 'character_building', 'Quran 76:8-9', 'Verse about those who feed the poor', 'generosity', 'A hungry boy faces a choice: keep his last date for himself or share it with a friend. Discover how his generous heart brings more blessings than he could imagine.', 10, true, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a peaceful little village, lived a boy named Amin. Amin had a heart full of kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-01.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One sunny afternoon, Amin found a single sweet date in his pocket. It was his favorite treat.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-02.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Amin felt hungry, but he knew his friend Samir was even hungrier. What could he do?', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-03.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Amin thought of the verse from the Quran about sharing with those in need. His heart felt light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-04.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Amin decided to share his last date with Samir. He knew it was the right thing to do.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-05.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Samir was surprised and happy. "Thank you, Amin!" he said with a big grin.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-06.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As Amin shared, he felt a warmth inside, like a soft, glowing light in his heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-07.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Suddenly, a gentle breeze blew and more dates fell from the tree above.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-08.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Amin and Samir laughed with joy, gathering the dates into their small hands.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-09.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Amin learned that sharing brings unexpected blessings, filling the heart with happiness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-10.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The sun began to set, painting the sky with shades of orange and pink.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-11.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'As they watched the sunset, Amin felt grateful for the beautiful day.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-12.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, '"Thank you for sharing with me," said Samir, "You''re a wonderful friend."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-13.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Amin smiled, feeling the goodness of his choice. "Allah loves those who share," he thought.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-14.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Soon, it was time to go home. The village lights twinkled softly in the evening.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-15.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As Amin tucked into bed, he felt calm and happy. He whispered, "Goodnight, world."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/boy-shared-last-date/page-16.webp' from public.stories where slug='boy-shared-last-date' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Bread Maker''s Secret', 'bread-maker-secret', 'rising_moons', '6-8', 'daily_life', 'Hadith about the blessings of work', 'Islamic teachings on honest labor', 'gratitude', 'A baker kneads dough with love and whispers gratitude with each fold. Discover the sacred in everyday work and humble provision.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a small village surrounded by lush green hills, lived a kind baker named Ibrahim. He awoke each morning before dawn, excited to start his day.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-01.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Ibrahim loved kneading dough. ''Alhamdulillah,'' he whispered with each fold, grateful for the chance to create something nourishing.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-02.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'His secret ingredient was gratitude. With every loaf, he whispered a prayer, thanking Allah for the simple yet profound joy of honest work.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-03.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Children loved visiting his shop after school, their eyes wide with wonder at the delicious treats lined up neatly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-04.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, '''Can you teach us to bake like you, Uncle Ibrahim?'' they often asked. He would smile warmly, ''One day, Insha''Allah. For now, enjoy what your hands can hold.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-05.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'One afternoon, Ibrahim shared his secret. ''It''s not just the flour or yeast,'' he explained, ''it''s the gratitude we put into each loaf.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-06.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The children tried it too. ''Thank you for this bread,'' they whispered as they kneaded. They giggled as the dough grew soft and warm.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-07.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'To their surprise, their bread turned out delightful, each loaf a little piece of magic filled with love and gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-08.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Ibrahim watched them with a heart full of joy, knowing the secret of the bread maker would live on in their hearts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-09.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'As the sun set over the village, the scent of fresh bread filled the air, a reminder of the blessings of honest work.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-10.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'In the quiet of the night, Ibrahim whispered a final prayer of thanks, feeling blessed for the day''s work.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-11.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'He knew that the true magic of his bread came from gratitude, making each loaf a gift to those who shared it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-12.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Ibrahim''s story reminds us to find joy in our work and to be grateful, for each task holds its own blessing.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-13.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As we drift to sleep, let''s remember Ibrahim and the secret he shared, finding gratitude in every corner of our lives.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-14.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Goodnight, dear child. May your dreams be filled with wonder and your heart with gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/bread-maker-secret/page-15.webp' from public.stories where slug='bread-maker-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Broken Vessel', 'broken-vessel', 'young_explorers', '9-12', 'character_building', 'Quran 94:5-6', 'With hardship comes ease', 'resilience', 'A vessel breaks and appears useless, but is repaired and becomes more beautiful. A metaphor for overcoming trials and growing stronger.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a small village nestled between lush green hills and vibrant wildflowers, a young potter named Amina lived with her family. Her fingers danced with clay, crafting vessels that were both beautiful and strong.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-01.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, while admiring her latest creation, an unexpected gust of wind knocked it off the table. The vessel shattered, pieces scattered across the floor. Amina''s heart sank as she looked at the broken pieces.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-02.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Amina''s father, a wise old potter, gently placed a hand on her shoulder. ''Do not worry, my child. Remember, with hardship comes ease. Let''s see what we can do with these pieces.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-03.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Together, they gathered the broken pieces and began the delicate task of repairing the vessel. Amina learned how to use a special golden lacquer to bind the shards together.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-04.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'As they worked, Amina''s father shared stories of old. ''In every challenge, there lies an opportunity for growth. This vessel will be more beautiful than before.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-05.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Days passed, and their work continued. Each piece was carefully placed, and the golden seams began to form a delicate pattern, turning the vessel into a unique masterpiece.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-06.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Finally, the vessel was complete. Its once unnoticed beauty was now enhanced by the golden lines that ran across its surface, telling a story of resilience and patience.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-07.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Amina realized that the vessel was not only whole again but far more exquisite than it had been. She felt a sense of pride and gratitude for the lesson she had learned.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-08.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Her father smiled gently, ''Remember, Amina, with every hardship comes ease, and what seems broken can become a source of beauty and strength.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-09.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Amina nodded, understanding now that hardships are not the end but rather a new beginning, a chance to become stronger and more beautiful.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-10.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'That night, as Amina lay in bed, she whispered a quiet prayer of thanks. She felt the warmth of her family''s love around her, comforting and secure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-11.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'With a heart full of hope, she drifted into a deep, peaceful sleep, knowing that with each new day, she would face challenges with courage and grace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/broken-vessel/page-12.webp' from public.stories where slug='broken-vessel' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Camel''s Lesson', 'camel-lesson', 'rising_moons', '6-8', 'daily_life', 'Hadith: The Prophet said, ''A good deed done to an animal is like a good deed done to a human being''', 'Sahih al-Bukhari 5663', 'compassion', 'A mistreated camel is rescued and cared for. Through this animal''s journey, learn about treating all creatures with dignity.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a bustling town surrounded by sand dunes, there lived a kind-hearted boy named Zayd. He loved exploring the desert with his best friend, a loyal camel named Jamal.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-01.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One evening, as they wandered home, Zayd noticed a thin, weary camel tied to a post. The camel''s eyes were sad, and its hump was low. Zayd felt a tug at his heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-02.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, '"Who does this camel belong to?" Zayd wondered out loud. No one answered, and the market stalls were closing. Zayd decided he couldn''t leave the camel alone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-03.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Zayd gently approached the camel, offering it water and a handful of dates. The camel nuzzled Zayd’s hand gratefully. Immediately, Zayd decided to bring it home.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-04.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'At home, Zayd''s family welcomed the camel with open arms. They named her Laila and gave her food and a soft place to rest. Laila''s eyes began to shine with happiness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-05.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Over the next few days, Zayd and his family cared for Laila. She grew stronger and happier each day. Zayd learned how much joy a little kindness could bring.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-06.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'One day, while walking with Jamal and Laila, Zayd saw a radiant figure speaking to a group of people. He recognized the Prophet, peace be upon him, by his presence.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-07.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Zayd listened as the Prophet, peace be upon him, spoke about kindness to all creatures. He said, "A good deed done to an animal is like a good deed done to a human being."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-08.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Zayd’s heart filled with joy. He realized that caring for Laila was a blessed act. He was grateful for the lesson he learned from her and the Prophet''s words.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-09.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'From that day on, Zayd promised to always show compassion to all living creatures. He knew that even small acts of kindness could make a big difference.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-10.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Years later, Zayd became known in his town for his gentle nature. People often came to him for advice on how to care for their animals.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-11.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Laila and Jamal remained by Zayd’s side, always reminding him of the lesson of compassion. Together, they touched many lives.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-12.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'As the stars twinkled one quiet night, Zayd whispered to Laila and Jamal, "Thank you for teaching me the true meaning of kindness."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-13.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The camels gently rested their heads on Zayd’s lap, their eyes reflecting the moonlight. It was a peaceful moment filled with gratitude and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-14.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, '"Goodnight, my dear friends," Zayd said softly. He closed his eyes, feeling a warm glow in his heart, knowing he was never alone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-15.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'The night was calm, and the desert wind sang a lullaby. The crescent moon shone brightly above, watching over Zayd and his beloved camels.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-16.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'In his dreams, Zayd wandered through lush gardens, where every creature lived in harmony. It was a world where kindness ruled, and every heart was light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-17.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'Zayd awoke the next morning, feeling refreshed and inspired. He thanked Allah for the blessings in his life and the lessons of compassion he had learned.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-18.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'With a heart full of gratitude, Zayd began his day, ready to spread kindness wherever he went, knowing that every small deed mattered.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-19.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'And so, Zayd, Laila, and Jamal lived happily, sharing their love and compassion with all. Under the watchful eyes of the stars, they were truly at peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/camel-lesson/page-20.webp' from public.stories where slug='camel-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Cave of Courage', 'cave-of-courage', 'young_explorers', '9-12', 'prophet_story', 'Quran 9:40', 'Story of Prophet Muhammad and Abu Bakr in the cave', 'courage', 'In a dark cave with enemies outside, a believer learns that true courage comes from faith. A powerful tale of trust and bravery.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Long, long ago, in the warm deserts of Arabia, the Prophet Muhammad and his loyal friend Abu Bakr found themselves seeking refuge. As the sun set, they arrived at a hidden cave, hoping it would be their sanctuary.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-01.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Inside the cave, darkness enveloped them. Yet, they felt a calm presence, knowing that they were not alone. The stars began to twinkle outside, as if watching over them.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-02.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Outside, the footsteps of those who sought harm could be heard. But Abu Bakr, with a heart full of faith, whispered, ''We have Allah with us. We need not fear.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-03.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'As the night deepened, the sound of wings fluttered. A pair of doves settled at the cave mouth, their soft coos filling the air with peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-04.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'A delicate spider spun its web across the cave''s entrance. Its silk shimmered like a silver curtain, concealing the cave with an unspoken promise of protection.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-05.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The pursuers arrived, searching high and low. But upon seeing the spider''s web and the resting doves, they concluded, ''No one could be inside.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-06.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Trusting in Allah, the Prophet and Abu Bakr knew their faith was their shield. The night was filled with silent prayers of gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-07.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'As dawn broke, the sky painted with hues of pink and gold, they knew their journey would continue, guided by faith''s eternal light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-08.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'With renewed strength, the Prophet and Abu Bakr stepped out, leaving the cave behind but carrying the lesson of courage within their hearts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-09.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The desert, now a friend, spread before them. Each step was a reminder that with true faith, the heart knows no fear.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-10.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The Prophet''s message, one of peace and courage, would soon touch the hearts of many, like ripples in a clear, serene pond.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-11.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'In a world often unsure, courage is a light within, guiding us through any darkness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-12.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'The Prophet Muhammad''s journey teaches us that even in solitude, our faith keeps us company and strong.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-13.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As the sun sets on this tale, remember that true strength lies in trust and belief, lighting up the path like brilliant stars.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-14.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Let courage be your companion, a gentle guide through your dreams tonight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-15.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As you close your eyes, imagine the warmth of the desert sun and the coolness of the cave, both cradling you in comfort.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-16.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'May your dreams be filled with faith, courage, and the gentle whispers of hope.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-17.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'Goodnight, dear one, with the wisdom of great stories wrapped around you like a cozy blanket.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-18.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'May the lessons of courage and faith guide you through every adventure of life.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-19.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'As the night sky watches over you, let the light of trust and love fill your heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-20.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'And when morning comes, may you rise with the courage of the Prophet and the steadfastness of Abu Bakr.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-21.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'Let your heart be brave, your steps sure, and your spirit filled with peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-22.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'Goodnight, with dreams full of promise and light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-23.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'Sleep well, dear one, wrapped in the gentle embrace of Allah''s love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cave-of-courage/page-24.webp' from public.stories where slug='cave-of-courage' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Cloud''s Purpose', 'cloud-purpose', 'little_stars', '3-5', 'quran_inspired', 'Quran 24:43', 'Description of how clouds are formed and bring rain', 'purpose', 'A fluffy cloud wonders what it''s for until it brings precious rain to a thirsty land. A gentle story about discovering our special purpose.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in the wide blue sky, there was a little fluffy cloud named Nubi.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-01.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Nubi watched other clouds form and drift by. ''What is my purpose?'' Nubi wondered.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-02.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'The sun shone brightly, and Nubi felt warm and cozy, yet still curious.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-03.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'One day, a gentle breeze called, ''Come along, Nubi! We have a journey to take.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-04.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Nubi floated along with the breeze, gathering tiny drops of water.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-05.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Slowly, Nubi grew bigger and fluffier, feeling a bit heavier.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-06.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, '''Why am I here?'' Nubi asked the sky. The sky whispered softly, ''Patience, little one.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-07.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Below, the earth was dry, and the plants were thirsty, waiting patiently.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-08.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Nubi felt a tug in its heart. ''Is it time?'' Nubi wondered, feeling ready.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-09.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Then, in a magical moment, Nubi released tiny raindrops to the land below.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-10.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The earth drank happily, and flowers began to bloom with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-11.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Nubi felt a warm glow inside. ''This is my purpose!'' Nubi realized joyfully.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-12.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, '''You did well,'' the sky said, as Nubi floated on with a happy heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-13.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As the sun set, Nubi felt the peace of knowing its special purpose.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-14.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Nubi settled in the night sky, whispering goodnight to the world below.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-15.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'The earth sighed contentedly, as Nubi drifted off to sleep, dreaming sweet dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/cloud-purpose/page-16.webp' from public.stories where slug='cloud-purpose' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Dawn Prayer''s Promise', 'dawn-prayer-promise', 'young_explorers', '9-12', 'daily_life', 'Quran 24:58', 'References to prayer times and spiritual devotion', 'peace', 'A young seeker discovers the transformative peace of morning prayer. A meditative story about spiritual awakening and starting fresh.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a small, serene village nestled between rolling hills, young Amina stirred at dawn. The air was crisp and whispered promises of a new day. She heard the gentle call of the Fajr prayer, a melody echoing through the morning mist.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-01.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Amina tiptoed to the window, gazing at the village bathed in the gentle embrace of dawn. Birds began their morning songs, and the world seemed to awaken with her. She felt a pull, a quiet invitation to join the world outside.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-02.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Her heart filled with a tranquil resolve, Amina wrapped her scarf around her and quietly descended the stairs. Her footsteps were light, as though she was walking on clouds. She was determined to experience the serenity promised by the morning prayer.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-03.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Outside, the world felt different, as if a gentle peace had settled over everything. Amina walked along the path, her feet brushing against the dewy grass. The mosque, standing tall and welcoming, awaited her arrival.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-04.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Inside the mosque, a warm light bathed the prayer hall. Amina joined the small group of devoted villagers, feeling the warmth of their shared faith. The Imam, a silhouette of calm, led the prayer with a voice that resonated with purity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-05.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As the prayer commenced, Amina felt her heart settle. The rhythmic verses of the Quran filled her with a peace she had never known. It was as though the words wrapped her in a gentle embrace, whispering secrets of tranquility.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-06.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'With each prostration, Amina felt a lightness within her soul. The worries she carried seemed to drift away with the morning breeze. She realized that the dawn prayer was not just a ritual, but a gift of renewal.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-07.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'When the prayer concluded, Amina lingered, savoring the stillness. She felt connected to something greater, a boundless peace that extended beyond the walls of the mosque. It was a feeling she wanted to carry with her throughout the day.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-08.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Stepping outside, Amina took a deep breath of the fresh morning air. The landscape before her seemed more vibrant, as though painted with richer colors. The world felt alive, and she was a part of its harmonious song.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-09.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'As she walked home, Amina noticed the small miracles of the morning — the dew-kissed flowers, the playful dance of the breeze, the soft glow of the rising sun. Each moment was a reminder of the creator''s handiwork.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-10.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Her heart swelled with gratitude, a quiet joy that whispered of hope and new beginnings. Amina understood that the dawn prayer was a promise — a promise of peace, of serenity, of a fresh start each day.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-11.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Returning home, Amina felt lighter, as though she had been given wings. She was ready to embrace the day, knowing that the peace she felt would guide her actions and thoughts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-12.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Her family greeted her with warm smiles, their eyes reflecting the morning''s promise. They too understood the magic of the dawn prayer, and together they shared a quiet moment of reflection.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-13.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As the day unfolded, Amina carried the morning''s peace within her. Every task was a joy, every interaction a chance to share the tranquility she had discovered. The dawn prayer''s promise was alive within her heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-14.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Even as the sun began its descent, Amina felt the lingering peace of the morning. She knew that the next dawn would bring a fresh promise, a new chance to awaken her spirit and embrace the world anew.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-15.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As night fell, Amina prepared for bed, her heart content and her mind at ease. The day''s peace wrapped around her like a comforting blanket, a reminder of the dawn prayer''s gentle promise.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-16.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'In the quiet of her room, Amina whispered a prayer of gratitude. She thanked Allah for the gift of peace, for the promise of each new dawn, and for the serenity that filled her heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-17.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'Her dreams that night were filled with visions of lush gardens, warm sunlight, and the soft sounds of morning prayers. Amina slept soundly, comforted by the promise of peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-18.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'The dawn prayer''s promise was a treasure she held close, a gift she carried with her into the world each day. Amina understood that this peace was a blessing, a gentle reminder to begin each day anew.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-19.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'As sleep beckoned, she smiled, knowing that the next morning would bring its own promise. The peace of the dawn prayer was a constant, a gentle guide through life''s journey.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-20.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'In her heart, Amina knew that the dawn prayer was more than just a moment of devotion. It was a time to connect, to find peace, and to renew her spirit. Every morning was a new beginning, a fresh promise.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-21.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'Wrapped in the gentle embrace of sleep, Amina dreamed of new beginnings and endless possibilities. Her heart was light, and her mind at peace, carried by the dawn prayer''s promise.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-22.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'The dawn''s promise whispered softly in her dreams, a lullaby of peace and hope. As Amina slept, she was surrounded by the love and serenity that the dawn prayer had gifted her.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-23.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'Goodnight, Amina. May the promise of peace guide your dreams and awaken your heart to a new day. Sleep well, dear child, knowing that the dawn prayer''s promise is always with you.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/dawn-prayer-promise/page-24.webp' from public.stories where slug='dawn-prayer-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Echo of Kindness', 'echo-of-kindness', 'rising_moons', '6-8', 'character_building', 'Hadith: ''None of you truly believes until he wishes for his brother what he wishes for himself''', 'Sahih Muslim 45 - Brotherhood and kindness', 'compassion', 'A child''s kind words echo through the village, returning magnified. Discover how goodness ripples through the community.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of a lush, green valley, there lived a young boy named Sami. Every morning, he greeted his neighbors with kind words and a warm smile.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-01.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, Sami noticed a lonely bird with a hurt wing. He gently wrapped it with a cloth and whispered, ''You''ll fly again soon, little friend.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-02.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Word of Sami''s kindness spread through the village. People began to greet each other more warmly, and smiles became contagious.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-03.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Sami''s mother noticed the change. ''Your kindness echoes like ripples in a pond,'' she said, hugging him tightly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-04.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'One evening, a stranger arrived at the village. Tired and weary, he asked for shelter. Sami''s family welcomed him with open arms.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-05.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The stranger shared stories of his journey, spreading joy and laughter. ''Your village feels like a warm embrace,'' he said gratefully.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-06.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As the stranger prepared to leave, he gifted Sami a small, shiny pebble. ''A token of your kindness,'' he smiled.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-07.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Sami''s heart swelled with joy. He realized that small acts of kindness could brighten the world, like stars lighting up the night sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-08.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Each night, Sami would look at the pebble, remembering the stranger''s words: kindness returns like an echo, louder and clearer.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-09.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'In time, the village became known for its warmth and compassion. Travelers felt at home, and friendships blossomed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-10.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Inspired by Sami, children began to help their parents, sharing toys and laughter, making the village a happier place.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-11.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Sami learned that true belief is wishing for others what you wish for yourself, a lesson that danced in his heart like a gentle breeze.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-12.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'And so, the echo of kindness continued, each act a note in a beautiful, endless melody of compassion.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-13.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As night fell, Sami whispered a prayer of gratitude, feeling peace wash over him like a calm river.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-14.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'With each new day, the village grew more beautiful, painted with the colors of kindness and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-15.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'And every night, as he drifted to sleep, Sami knew his heart was a part of something much greater.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-16.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The echo of kindness had changed the village, and it had all started with a simple, heartfelt smile.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-17.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'So, when you lay down tonight, remember that your kind heart can light up the world, just like young Sami''s.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-18.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'And with that thought, close your eyes, and let your dreams be filled with the wonders of kindness and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-19.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'Goodnight, dear one. May your dreams be as sweet and kind as your heart. Peaceful slumber and sweet dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/echo-of-kindness/page-20.webp' from public.stories where slug='echo-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Elder''s Gift', 'elder-gift', 'rising_moons', '6-8', 'character_building', 'Hadith: ''The best of you are those who have the best manners and character''', 'Al-Tirmidhi - Akhlaq (Good Character)', 'respect', 'An elderly teacher gives the greatest gift: the wisdom of patience and understanding. Learn why experience and kindness matter.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a peaceful village surrounded by lush green fields, lived an elder named Zahra. She was wise and kind, known for her gentle ways. The children loved visiting her, always eager to learn from her stories.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-01.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One sunny afternoon, a group of children sat in a circle as Zahra began her tale. ''Long ago, I learned that patience and understanding can change the world around us,'' she started, her voice soothing like a gentle breeze.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-02.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Little Amina, curious and bright, asked, ''How can patience change anything?'' Zahra chuckled softly, ''Ah, dear Amina, let me share a story of a time when patience was my greatest friend.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-03.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Zahra spoke of her younger days, when she struggled to learn the craft of weaving. ''I wanted to quit many times,'' she confessed, ''but each mistake taught me something new.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-04.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, '''With each passing day, my patience grew, and so did my skill,'' Zahra continued. ''I learned to weave beautiful carpets that told stories of our village.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-05.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Ali, a thoughtful boy, asked, ''Did you ever get angry?'' Zahra nodded, ''Yes, Ali, but I learned that anger can blind us, while patience shows us the way forward.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-06.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, '''One day, a traveler saw my carpets and marveled at them,'' Zahra shared. ''He asked how I learned such skill, and I told him it was from embracing patience and understanding.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-07.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The children listened in awe, imagining the carpets that brought stories to life. Zahra smiled warmly, ''Patience helped me see beauty where others saw only threads.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-08.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Little Sami, always playful, asked, ''Can patience help me learn to climb the tallest tree?'' Zahra laughed gently, ''Yes, patience can help you reach any height, dear Sami.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-09.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, '''Remember, children,'' Zahra advised, ''our Prophet taught that the best of us are those who have the best manners and character. Patience is part of that character.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-10.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As the sun began to set, the children thanked Zahra for her story, feeling inspired and calm. Zahra watched them leave with a heart full of hope and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-11.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'That night, under a sky full of twinkling stars, the children dreamed of patience and understanding, their hearts warmed by Zahra’s gentle wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/elder-gift/page-12.webp' from public.stories where slug='elder-gift' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Fair Judge', 'fair-judge', 'young_explorers', '9-12', 'islamic_history', 'Quran 4:58', 'Verse about just administration', 'justice', 'A fair ruler must judge between two parties seeking justice. Through wisdom and impartiality, learn how justice serves the community.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the ancient lands of Arabia, there lived a wise ruler known for his fairness. He was beloved not just by his people, but by all who heard of his justice. Each day, he would listen to the concerns of those who came to him, treating everyone with equal respect.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-01.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One morning, two merchants arrived at the palace, each claiming ownership of a beautiful, intricately woven carpet. The ruler, known for his patience, invited them to speak their truth. The merchants, both earnest and passionate, pleaded their cases.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-02.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'The first merchant spoke of how he had traded many goods to acquire the carpet, while the second claimed it was unfairly taken from him by deceit. The ruler listened intently, nodding thoughtfully as each presented their arguments.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-03.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'After hearing both sides, the ruler requested a short pause, allowing them to reflect on the importance of honesty and fairness. He encouraged them to remember their shared values and the teachings of their faith.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-04.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'With calm resolve, the ruler proposed a solution. He suggested that the carpet be sold, and the proceeds divided equally. This way, neither would feel cheated, and they could maintain their friendship.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-05.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The merchants agreed, recognizing the wisdom in the ruler''s judgment. They shook hands, their hearts light with relief and gratitude. The ruler smiled, knowing justice had prevailed once more.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-06.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As the merchants left, the ruler turned to the gathered crowd, imparting a gentle reminder of the importance of justice. He encouraged them to treat one another with fairness and kindness in every dealing.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-07.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The sun dipped below the horizon, casting a serene blue over the city. The ruler returned to his chambers, his heart at peace. His work was done for the day, but his commitment to justice would continue.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-08.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'That night, as the ruler rested, he dreamt of a world where justice and kindness were the norm. His dreams were filled with lush gardens and harmonious communities.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-09.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The morning sun peered over the horizon, promising a new day filled with opportunities for justice and peace. The ruler awoke, ready to continue his noble task.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-10.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The ruler knew that each day was a chance to inspire others to live by the principles of fairness and truth. His heart was full of hope and determination.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-11.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'As the day unfolded, the ruler continued to listen and guide his people, ensuring that justice always took root in their hearts. His wisdom, like the sun, illuminated the path for those who sought his counsel.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-12.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Through his actions, the ruler taught that fairness was not just a measure of the law, but a way of life. His example inspired generations to come.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-13.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'And so, with each passing day, the ruler''s legacy grew. The city thrived under his wise and gentle guidance, a beacon of justice and peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-14.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'The fair ruler''s story traveled far and wide, touching hearts with its message of integrity and kindness. People everywhere aspired to follow his example.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-15.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Through the teachings of their faith, the people understood that justice was a divine gift meant to be cherished and upheld. It strengthened their bonds and brought peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-16.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'As the story of the fair judge ended, it left a warm glow in the hearts of all who heard it, reminding them of the beauty that justice brings to life.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-17.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'In the stillness of night, the city rested, cradled in the knowledge that justice would always guide them to brighter days.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-18.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'The ruler, serene in his chambers, knew his duty was far from over. Tomorrow would bring new challenges, new stories, and new acts of fairness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-19.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'And as everyone drifted into dreams, the lesson of justice lingered in their hearts, a gentle reminder of the goodness it fosters.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-20.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'For in the land of the fair judge, justice was not just a decision but a way of life that united all in harmony.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-21.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'And so, the fair judge’s legacy lived on, a guiding light for all who believed in the power of fairness and truth.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-22.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'As night fell again, the city whispered a promise, to cherish justice and hold it dear, as they wished each other a peaceful goodnight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-23.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'And so, nestled in their beds, the children of the city drifted off to sleep, wrapped in the warmth of a just world, where goodness and peace prevail.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fair-judge/page-24.webp' from public.stories where slug='fair-judge' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Faithful Servant', 'faithful-servant', 'rising_moons', '6-8', 'character_building', 'Quran 16:36', 'About serving with faith and sincerity', 'dedication', 'A humble servant does their work with complete devotion. Discover that dignity comes not from status, but from sincere effort.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a vibrant village, there was a humble servant named Amal. She worked in the grand house of the kind Sheikh. Every day she awoke with a smile, ready to serve with a heart full of sincerity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-01.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Amal''s tasks were many, but she never complained. She swept the halls, polished the windows, and tended to the garden with care. Her dedication was like the sun, shining brightly for all to see.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-02.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, as Amal worked in the garden, she noticed a small bird struggling to fly. Without hesitation, she gently scooped it up, whispering soothing words until it was strong enough to soar.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-03.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'The Sheikh watched Amal from a distance, impressed by her kindness and devotion. He approached her and said, ''Amal, your heart is pure, and your work is noble. You inspire us all.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-04.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Amal blushed at the Sheikh''s words. ''Thank you, kind Sheikh,'' she replied. ''I serve not for praise, but because it fills my heart with joy.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-05.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The villagers began to notice Amal''s dedication, and she became a beacon of light for them. Her sincerity and faith lit up their hearts, teaching them the beauty of serving with love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-06.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'One evening, as the sky turned a deep blue, Amal sat by the river, reflecting on her day. ''Alhamdulillah,'' she whispered, grateful for the strength to serve with sincerity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-07.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The stars began to twinkle in the sky, and Amal knew that true dignity comes not from wealth or status, but from a heart dedicated to serving with love and faith.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-08.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As Amal prepared to sleep, she felt a comforting warmth surround her. It was the warmth of knowing she had touched lives with her sincerity and dedication.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-09.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The village was quiet, and the gentle whispers of the night cradled Amal to sleep. She knew that dedication was her strength, and with it, she could illuminate the world.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/faithful-servant/page-10.webp' from public.stories where slug='faithful-servant' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Forgotten Well', 'forgotten-well', 'rising_moons', '6-8', 'islamic_history', 'References to wells in Islamic history and the Prophet''s practices', 'Historical significance of wells in Islamic civilization', 'justice', 'A village''s old well is abandoned until one child remembers its value. Together, they restore it and bring the community back together.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of a sunlit village, surrounded by fields of green, lay an old well, forgotten by all.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-01.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Yasmin, a curious girl with bright eyes, asked her grandmother about the well. ''Once, it gave us the purest water,'' her grandmother said.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-02.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Yasmin pondered, ''Why did we stop using it?'' Her grandmother sighed, ''People forgot its value as the village grew.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-03.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Determined, Yasmin decided to visit the well. She felt a sense of wonder as she approached its ancient stones.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-04.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The stones were cool to the touch. Yasmin imagined the many hands that once drew water from it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-05.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Yasmin called her friends. Together, they decided to clean the well, imagining its waters flowing once more.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-06.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The children worked hard. They cleared weeds and swept the stones, laughing and chatting under the sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-07.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Soon, the well stood proud and clean. Yasmin peered down, seeing her reflection in the clear water.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-08.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'That night, Yasmin dreamed of the well during the Prophet Muhammad''s time, where people gathered with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-09.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The next day, the villagers noticed the change. They praised Yasmin and her friends for their efforts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-10.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The well, once forgotten, now became the village''s heart again, a symbol of unity and care.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-11.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Yasmin learned that justice was not just about grand gestures but in remembering what truly matters.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-12.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'As the stars twinkled above, Yasmin felt a gentle peace, knowing she had made a difference.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-13.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The well''s waters flowed, bringing life and joy to all around, a reminder of the Prophet''s teachings.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-14.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Yasmin''s heart was full, knowing she had followed the path of justice and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-15.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As she lay in bed, she whispered a prayer of gratitude, surrounded by love and peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-16.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The village slept soundly, united by the well''s gentle ripple, dreaming of a bright tomorrow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-17.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'And so, with the well restored, the village was whole again, a testament to the power of remembrance.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-18.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'Yasmin knew that justice was alive in the little acts of kindness and care. The well was her proof.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-19.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'And with that, the world felt right again, cradling Yasmin in its gentle embrace. Goodnight, sweet dreamer.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/forgotten-well/page-20.webp' from public.stories where slug='forgotten-well' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Fortress of Faith', 'fortress-of-faith', 'young_explorers', '9-12', 'prophet_story', 'Quran 2:285', 'Verse about faith and Allah''s protection', 'trust_in_allah', 'A soldier learns that true protection comes not from walls of stone, but from unwavering faith. A powerful tale of spiritual strength.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a bustling city surrounded by tall stone walls, there lived a soldier named Zayd. He believed the walls were mighty because they stood firm, protecting the city from harm.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-01.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, an old traveler arrived at the city gates, speaking of a different kind of strength. ''True protection,'' he said, ''lies not in stone, but in the faith we carry within our hearts.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-02.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Zayd was puzzled. How could something as invisible as faith be stronger than the walls? Yet, the traveler''s words echoed in his mind, sparking a light of curiosity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-03.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'That night, Zayd lay awake, thinking about the traveler''s words. He decided to seek guidance from a wise scholar known for his knowledge and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-04.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The scholar, with a gentle smile, shared stories of the prophets, whose faith in Allah was their strongest fortress. ''Allah''s protection is a shield unmatched by any earthly barrier,'' he explained.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-05.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Inspired, Zayd began to understand. Faith was like a gentle breeze, unseen yet felt, guiding and protecting those who trust in it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-06.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As days passed, Zayd''s heart grew stronger. He prayed with sincerity, feeling the warmth of faith envelop him like a comforting embrace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-07.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The city faced a great storm, and Zayd found himself reassuring others. ''Have faith,'' he said, ''for Allah is with those who believe.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-08.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The storm passed without harm, leaving the city unharmed. People marveled at how Zayd''s faith had become their true fortress during the trial.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-09.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Zayd''s journey taught him that faith, like love, grows stronger when shared. The city thrived, its people united by the invisible bonds of trust in Allah.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-10.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As the years passed, Zayd became known as a symbol of faith. His story spread far and wide, inspiring many to find strength beyond the visible.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-11.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'And so, the city lived in peace, protected not just by walls of stone, but by the unyielding faith that filled each heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/fortress-of-faith/page-12.webp' from public.stories where slug='fortress-of-faith' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Garden''s Guardian', 'garden-guardian', 'little_stars', '3-5', 'daily_life', 'Quran 2:35', 'Reference to the Garden of Eden', 'responsibility', 'A young gardener tends to flowers with love and care. Watch as the garden blooms into a sanctuary where everyone feels welcome.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a lush green garden, a young gardener named Samir loved every plant.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-01.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Samir woke up early each morning. He whispered to each flower, ''Grow strong and bloom bright!''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-02.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'The flowers listened to Samir and stretched their petals wide. The garden was a rainbow of colors.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-03.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'One day, a little bird flew into the garden. ''Welcome,'' chirped Samir, ''This is your home too!''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-04.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The bird was happy. It sang sweet songs and danced from branch to branch.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-05.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Samir watched with delight. The garden was not just his; it was a home for all.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-06.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'A gentle breeze whispered through the trees. It was like a soft, loving hug for everyone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-07.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Every day, the garden grew more beautiful. Flowers, birds, and even butterflies came to visit Samir.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-08.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'One afternoon, a wise old owl settled in a tree. ''You are a true guardian, Samir,'' it hooted.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-09.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Samir felt proud. He knew the garden was happy because it was loved and cared for.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-10.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Soon, the stars began to twinkle in the sky. The garden became a magical place under the moonlight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-11.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Samir yawned, feeling sleepy. He whispered goodnight to his garden friends.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-12.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'He knew he had done well. The garden would be safe and loved until morning.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-13.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As Samir drifted to sleep, the garden hummed a lullaby. All was calm and peaceful.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-14.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'In the quiet of the night, the garden glowed softly, waiting for another day of love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-15.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Goodnight, little one. May your dreams be as sweet and gentle as Samir''s garden.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/garden-guardian/page-16.webp' from public.stories where slug='garden-guardian' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Grateful Hearts', 'grateful-hearts', 'little_stars', '3-5', 'character_building', 'Quran 31:12', 'Be grateful to Allah', 'gratitude', 'Three siblings find simple joy in small blessings. A heartwarming tale about counting our gifts and saying thank you.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a sunny village, lived three happy siblings: Amina, Omar, and little Sami.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-01.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, they sat under a big, shady tree, talking about their favorite things.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-02.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, '"I love the sound of birds singing," Amina said, smiling at the sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-03.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, '"I enjoy the smell of flowers," Omar added, touching a bright daisy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-04.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, '"I love the taste of sweet fruits," giggled Sami, munching an apple.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-05.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Mama joined them, noticing their joy. "Remember," she said, "always be grateful for these blessings."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-06.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'That evening, they gathered for supper, thankful for the warm food.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-07.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Amina whispered, "Thank you, Allah, for all that we have."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-08.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, '"Yes, thank you for the laughter and love," said Omar.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-09.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Sami hugged his teddy bear, nodding with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-10.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As bedtime came, they lay in their cozy beds, feeling safe and loved.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-11.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The night sky twinkled with stars, a gentle reminder of Allah''s blessings.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-12.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, '"Goodnight, my darlings," Mama whispered, kissing their foreheads.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-13.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The siblings dreamed of happy days and beautiful gifts from Allah.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-14.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'In their hearts, they knew, being grateful brings endless joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-15.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'And with grateful hearts, they drifted off into sweet dreams. Goodnight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/grateful-hearts/page-16.webp' from public.stories where slug='grateful-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Healer''s Herbs', 'healer-herbs', 'rising_moons', '6-8', 'daily_life', 'Hadith about Allah''s cure for every ailment', 'Islamic teachings on healing and medicine', 'compassion', 'A village healer gathers herbs to help the sick. This gentle story celebrates the mercy of those who dedicate themselves to caring.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a quaint village, where the sun kissed the earth with warmth, lived Layla, the healer. She was known for her gentle touch and kind heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-01.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Every morning, Layla set out to gather herbs. The villagers would greet her with smiles, knowing she would help those in need.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-02.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, Layla met a little boy named Amir. He was sitting by the path, looking sad. His mother was unwell, and he was worried.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-03.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, '"Do not worry, Amir," Layla said softly. "Allah has given us cures for every ailment. Let''s find the right herbs for your mother."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-04.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Together, they journeyed through the fields. Layla showed Amir the plants and explained their healing properties.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-05.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Amir listened with wonder. He felt hopeful, knowing that the earth held secrets to help his mother heal.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-06.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As they returned, Amir noticed the caring smiles of the villagers. Kindness was everywhere, in every heart and every hand.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-07.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Layla prepared a soothing brew for Amir''s mother, whispering prayers as she worked.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-08.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Amir watched eagerly. His heart was filled with gratitude. He knew that compassion was the greatest healer of all.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-09.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Soon, Amir''s mother felt better. She smiled at Layla, thankful for her help and the blessings of the cure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-10.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Layla''s heart swelled with joy. Helping others filled her life with purpose and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-11.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'As she walked home, Layla whispered a prayer for all those who needed healing, feeling grateful for Allah''s guidance.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-12.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'The village settled into a calm slumber, wrapped in the warmth of compassion and caring hearts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-13.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Amir fell asleep, dreaming of a garden filled with magical herbs and a healer who brought smiles to many.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-14.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Layla knew that compassion was a light in the darkness, guiding her path as she cared for others.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-15.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'The stars twinkled above, as if whispering secrets of the universe, a reminder of Allah’s mercy and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-16.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The healer’s herbs were more than just plants; they were symbols of hope, kindness, and Allah’s abundant mercy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-17.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'As the night deepened, the village rested, secure in the warmth of Layla''s care and the promise of a new dawn.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-18.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'In the quiet, Layla whispered a final prayer, thankful for the chance to help and heal.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-19.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'With a heart full of peace, Layla drifted to sleep, dreaming of gardens and stars, warmth and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/healer-herbs/page-20.webp' from public.stories where slug='healer-herbs' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Honest Fisherman', 'honest-fisherman', 'little_stars', '3-5', 'character_building', 'Hadith: The Prophet said, ''The best of you are those who are best to their families, and I am the best among you''', 'Tirmidhi 3895 - Honesty and truthfulness', 'honesty', 'A fisherman finds something precious in his nets. His choice to return it teaches us that honesty is worth more than anything.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, by the sparkling sea, lived a kind fisherman named Ali.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-01.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Every day, Ali sailed his little boat and cast his nets into the deep blue sea.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-02.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One sunny morning, Ali found something shiny tangled in his nets.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-03.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'It was a beautiful golden necklace, gleaming brightly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-04.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Ali thought, ''This must belong to someone. I should return it.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-05.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'He sailed back to the village, ready to find the owner.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-06.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Ali asked his neighbors, ''Did anyone lose a golden necklace?''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-07.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'A worried lady came forward. ''I lost it!'' she said with relief.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-08.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Ali smiled, ''Here it is. I''m glad I found you.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-09.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The lady thanked Ali, ''You''re so honest!''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-10.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Ali felt happy. Being honest made him feel good inside.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-11.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Every day, Ali continued to fish, always honest and true.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-12.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'The villagers loved Ali for his honesty and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-13.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Ali knew honesty was more precious than any treasure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-14.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'As the sun set, Ali whispered a prayer of gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-15.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Good night, little ones. Be honest like Ali, and sleep peacefully.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/honest-fisherman/page-16.webp' from public.stories where slug='honest-fisherman' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The King''s Secret', 'king-secret', 'young_explorers', '9-12', 'prophet_story', 'Quran 18:39-44', 'Story of the two gardens - humility vs. arrogance', 'humility', 'A proud king learns that his greatest wealth cannot protect him from loss. Discover why humility is the truest sign of power.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a land of lush gardens and sparkling streams, there was a mighty king. He possessed two magnificent gardens, filled with the most fragrant flowers and bountiful fruits. His wealth and power were known throughout the land.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-01.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'The king would often wander through his gardens, admiring his wealth. ''Surely, nothing can ever take this fortune away,'' he would think, as he gazed upon his vast lands. His heart grew proud, and he felt invincible.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-02.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, a wise man visited the king. He spoke gently, ''With every blessing comes a test. Remember, it is humility that truly enriches the heart.'' The king listened, but his mind was clouded by pride.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-03.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Over time, the king noticed that one of his gardens was not as vibrant as before. The flowers began to wilt, and the streams ran dry. His heart was troubled, but he dismissed it, thinking his other garden would suffice.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-04.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Seasons passed, and the once-glorious gardens became barren. The king, now humbled, remembered the wise man''s words. He realized that true strength lay in gratitude and humility, not in the riches he once held dear.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-05.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The king embraced humility, caring for his remaining lands with love and gratitude. As he did, his heart felt lighter, and he found joy in the simple beauty of each day. His people admired him, not for his wealth, but for his newfound wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-06.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The king learned that when he shared his blessings, they multiplied beyond measure. His heart, once heavy with pride, was now light with humility. He found peace in knowing that true wealth lay not in possessions, but in the heart''s openness to gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-07.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'As the sun set on the kingdom, the king sat in his garden, watching the colors dance across the sky. He whispered a prayer of thanks, feeling the gentle embrace of humility surrounding him like a cherished friend.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-08.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The night wrapped the kingdom in a soft, starry blanket. The king''s heart was content, knowing that he had found the greatest treasure of all. He closed his eyes with a smile, feeling the warmth of humility and gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/king-secret/page-09.webp' from public.stories where slug='king-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Light of Patience — The Story of Young Yusuf', 'light-of-patience-yusuf', 'rising_moons', '6-8', 'prophet_story', 'Quran 12:4-6', 'Story of Prophet Yusuf''s early life and dreams', 'patience', 'Young Yusuf has a beautiful dream, but his journey is not easy. Learn how patience and trust in Allah guide him through dark times toward the light.', 15, true, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in the warm sands of ancient Canaan, lived a young boy named Yusuf. He had ten older brothers and loved his father very much.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-01.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One night, Yusuf had a wondrous dream. He saw eleven stars, the sun, and the moon, all bowing down to him. Curious, he ran to tell his father.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-02.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, '"Oh Father," Yusuf said, "I''ve seen stars, the sun, and the moon bowing to me!" His father smiled warmly, listening with loving attention.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-03.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'His father, wise and gentle, said, "My dear Yusuf, this dream is special. Allah has a plan for you. But be patient and do not share it with your brothers."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-04.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Yusuf loved his father and trusted him. But his journey was not easy. His brothers were often jealous of the love he received.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-05.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Despite the challenges, Yusuf kept his father''s words in his heart. He learned the importance of patience and put his trust in Allah.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-06.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'One day, his brothers took him far from home. Yusuf felt alone, but his heart remembered his father''s love and his trust in Allah.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-07.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'In the silence of the night, Yusuf prayed. He knew that Allah was always with him, watching over him like a gentle guardian.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-08.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As days turned into weeks, Yusuf''s patience grew stronger. He never lost hope, waiting for Allah''s plan to unfold.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-09.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Yusuf''s journey was long, but he remembered the dream, and it gave him strength. He trusted that Allah would guide him.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-10.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'In time, Yusuf''s patience was rewarded. He grew wise and kind, becoming a beloved leader, just as his dream had foretold.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-11.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Through his trials, Yusuf learned that patience and trust in Allah are like light in the darkness, guiding us home.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-12.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Yusuf remembered his father''s words and smiled. Patience had been his guide, and now, he was home.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-13.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As night fell, Yusuf looked at the stars, remembering the dream that started it all. He whispered a prayer of gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-14.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'He knew that with patience, everything would be alright. Allah''s light would always shine upon those who trust in Him.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-15.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, '"Goodnight, dear Yusuf," the stars seemed to say, as they twinkled gently in the night sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-16.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'Yusuf closed his eyes, feeling safe and content. He knew Allah was watching over him, always.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-17.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'And so, young Yusuf''s story reminds us all that patience and faith can lead us to the brightest of places.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-18.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'May we all sleep with dreams as beautiful as Yusuf''s, and hearts as patient and trusting.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-19.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'Goodnight, dear child. Sleep well, knowing that Allah''s light is always with you.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/light-of-patience-yusuf/page-20.webp' from public.stories where slug='light-of-patience-yusuf' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Lion''s Mercy', 'lion-mercy', 'rising_moons', '6-8', 'islamic_history', 'Quran 60:8-9', 'Verses about mercy and justice', 'compassion', 'A powerful lion chooses mercy over revenge. Through this majestic tale, discover that true strength lies in compassion.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of a lush, green jungle, there lived a mighty lion named Asad. Asad was known as the king of the jungle for his strength and courage.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-01.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, Asad heard a commotion nearby. Curious, he padded softly through the trees to see what was happening.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-02.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'He found a small group of animals gathered together, looking fearful and worried. "What''s wrong?" Asad asked gently.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-03.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, '"There is a hunter in the jungle," the deer said. "He set traps to catch us, and we are afraid."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-04.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Asad thought for a moment. "Let us find this hunter together," he suggested. "Perhaps we can make him understand the harm he does."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-05.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'They moved quietly through the jungle, led by Asad''s keen senses. Soon, they found the hunter, stuck in one of his own traps.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-06.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The hunter looked at Asad with fear in his eyes, expecting the lion to take revenge. But Asad had a different plan.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-07.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, '"I will set you free," Asad said softly. "But promise to leave the jungle and never harm us again."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-08.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The hunter, shocked by the lion''s mercy, nodded quickly. "I promise," he said, grateful for the second chance.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-09.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Asad and the animals helped untangle the hunter from the trap. Once free, he hurried away, never to return.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-10.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The animals thanked Asad for his wisdom. "You are truly a compassionate king," the rabbit said.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-11.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, '"Compassion is the greatest strength," Asad replied, his eyes gentle and kind.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-12.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'That night, as the stars twinkled above the jungle, Asad lay down to sleep, feeling peaceful and content.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-13.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The animals gathered around him, feeling safe and protected in the jungle they called home.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-14.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, '"Goodnight, King Asad," the animals whispered. "Your kindness has made the jungle a better place."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-15.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Asad smiled, his heart filled with joy, knowing he had chosen the path of mercy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-16.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'He drifted into a gentle sleep, dreaming of a world where all creatures live in harmony.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-17.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'In the quiet of the night, the jungle echoed with the sound of calm and peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-18.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'Asad knew that tomorrow would bring new adventures and more chances to spread kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-19.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'Goodnight, dear child. May your dreams be filled with the magic of mercy and the beauty of compassion.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lion-mercy/page-20.webp' from public.stories where slug='lion-mercy' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Little Ant''s Big Thank You', 'little-ant-big-thank-you', 'little_stars', '3-5', 'prophet_story', 'Quran 27:18-19', 'Story of Prophet Sulayman and the ants', 'gratitude', 'A tiny ant learns the power of saying thank you when Prophet Sulayman''s army passes by. Join this little creature as it discovers that gratitude is the biggest gift we can give.', 10, true, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Deep in the lush green forest, a tiny ant named Anisa lived with her family.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-01.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One sunny morning, Anisa heard a rumbling sound. The ground shook gently.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-02.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Anisa saw a grand procession of soldiers marching. It was Prophet Sulayman''s army!', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-03.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Anisa hurried back to warn her friends, ''Quick, get inside! The army is coming!''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-04.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The ants quickly hid underground, safe and sound.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-05.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Above, Prophet Sulayman smiled kindly, understanding the ants'' words.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-06.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'He spoke softly to his army, ''Be careful not to harm the tiny ants.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-07.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Anisa peeked out and saw the army move gently around them.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-08.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Her heart filled with gratitude, and she whispered, ''Thank you, dear Prophet.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-09.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The other ants joined in, their tiny voices full of thanks.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-10.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Prophet Sulayman continued his journey, smiling at the ants'' gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-11.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Anisa learned that saying ''thank you'' was a gift she could give.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-12.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'She felt warm and happy inside, knowing she had shared her gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-13.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The forest grew quiet as the sun set, painting the sky in colors.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-14.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Anisa snuggled into her cozy bed, feeling safe and loved.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-15.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Goodnight, little Anisa. Sleep tight with a heart full of gratitude.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/little-ant-big-thank-you/page-16.webp' from public.stories where slug='little-ant-big-thank-you' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Lost Caravanserai', 'lost-caravanserai', 'young_explorers', '9-12', 'islamic_history', 'Historical references to Islamic trade routes and waystations', 'Inspired by the caravanserai system during Islamic Golden Age', 'justice', 'A traveler must find a legendary caravanserai where justice reigns. Follow this adventure as it explores mercy, fairness, and integrity.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of the bustling market town of Samir, young Tariq listened eagerly to the stories told by travelers. They spoke of a legendary caravanserai, a place where justice was served with fairness and wisdom. It was said to be hidden along the ancient trade routes, known only to a few.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-01.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Tariq decided to embark on a journey to find this legendary place. With a satchel packed and his loyal camel, Jamal, by his side, he set out under the golden rays of dawn. The air was filled with the promise of adventure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-02.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'As days turned into weeks, Tariq traveled through lush oases and across vast deserts. He met people from different lands, each sharing tales of the caravanserai where justice reigned. Some spoke of its beauty, while others mentioned the wisdom of its keepers.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-03.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'One evening, as the sun dipped below the horizon, casting the world in shades of orange and pink, Tariq arrived at a crossroad marked by an ancient stone. A traveler pointed him towards a path less traveled, whispering that it led to the caravanserai.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-04.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Guided by the stars, Tariq ventured down the secluded path. The night was peaceful, and the only sound was the gentle tread of Jamal. Tariq felt hopeful, his heart guided by stories of justice and mercy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-05.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The following morning, Tariq''s eyes widened as he beheld the legendary caravanserai. Its walls glowed with the warmth of the morning sun, and a gentle breeze carried the scent of blooming jasmine. Here, justice and fairness were more than ideals—they were a way of life.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-06.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Inside, Tariq witnessed wise men and women resolving disputes with kindness and equity. Merchants from distant lands came to trade not just goods, but ideas and stories, enriching their lives with shared knowledge and respect.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-07.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Tariq learned that the secret of this place was not magic, but the values of compassion and fairness practiced by its people. He realized that true justice began with understanding and respect for others.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-08.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As days turned to weeks, Tariq felt at home in this haven of justice. He knew he had found more than just a place—he had discovered a way of living that he would carry with him always.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-09.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'When it was time to leave, Tariq bid farewell to his new friends, promising to return. With a heart full of gratitude, he and Jamal set off, the path ahead brighter with the light of the lessons he had learned.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-10.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As the caravanserai disappeared into the horizon, Tariq felt a gentle peace. He understood that the journey was far from over. With each step, he carried with him the spirit of justice and integrity, ready to share it with the world.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-11.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The stars began to twinkle as night embraced the desert once more. Tariq settled beside a small fire, his heart content. He felt the warmth of the caravanserai in his heart, knowing he carried its lessons wherever he went.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-12.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'He whispered a prayer of thanks for the journey and the knowledge he had gained. As he drifted into sleep, Tariq knew that justice, like the gentle night, was a comfort that wrapped around the world.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-13.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Under the starlit sky, the desert whispered its ancient secrets. Tariq dreamt of a world where fairness and mercy were as boundless as the sands, and the caravanserai was a beacon of hope for all who sought it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-14.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'In his dreams, Tariq saw distant lands where justice was sown like seeds, growing into strong, towering trees of peace. He knew his journey had just begun, with endless paths to discover and stories to tell.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-15.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'The moon watched over him as he slept, a gentle guardian of the night. The desert was silent, save for the soft rustle of the wind, carrying with it the stories of travelers like Tariq, who journeyed in search of truth and justice.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-16.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'Tariq''s dreams were filled with the faces of those he had met on his travels—each a part of his story, each a lesson in compassion and fairness. He knew their kindness was a gift he would cherish forever.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-17.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'With a heart lightened by hope, Tariq awoke to the soft glow of dawn. The world felt new and filled with promise. He knew that as long as he carried the spirit of the caravanserai, his path would always be guided by justice.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-18.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'As he continued his journey, Tariq shared the stories he had learned, planting seeds of justice and kindness wherever he went. The world, he realized, was his caravanserai—a place where fairness could thrive.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-19.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'Tariq''s heart was full as he thought of the friends he had made and the wisdom he had gathered. He understood that justice was a journey, not a destination, and he was grateful for every step along the way.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-20.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'The sun set in the west, painting the sky in hues of orange and pink. Tariq looked ahead with determination, knowing that the lessons of the caravanserai would guide him through all of life''s adventures.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-21.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'As darkness embraced the land once more, Tariq settled under the stars, feeling the presence of the caravanserai in his heart. Justice, he knew, was a light that shone brightest in the darkest nights.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-22.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'Tariq''s eyes grew heavy, and he drifted into a restful sleep, dreaming of a world where kindness and fairness reigned. His adventures had only just begun, but he knew he was never alone on his journey.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-23.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'Goodnight, dear traveler. May your dreams be filled with the wisdom of the caravanserai, and may your heart always be guided by justice and love. Sleep well, knowing the world is a brighter place because of you.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-caravanserai/page-24.webp' from public.stories where slug='lost-caravanserai' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Lost Tradition', 'lost-tradition', 'young_explorers', '9-12', 'islamic_history', 'References to Islamic scholarly traditions', 'Historical narratives of learning and knowledge transmission', 'heritage', 'A youth discovers a forgotten tradition of his ancestors and works to restore it. Learn about honoring our roots and identity.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of an ancient city, young Tariq loved to wander the cobbled streets, listening to tales of the past. His grandmother often spoke of a time when scholars illuminated the world with their knowledge.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-01.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, Tariq discovered an old, dusty manuscript in his grandmother’s attic. It spoke of a forgotten tradition of knowledge sharing called the Circle of Light, once cherished by his ancestors.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-02.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Curiosity ignited, Tariq decided to learn more about the Circle of Light. He visited the grand library, a place of whispers and secrets, where the wisdom of ages was kept safe.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-03.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'A kind librarian noticed Tariq’s interest and guided him to a special section. Here, books written by great Islamic scholars told stories of discovery and enlightenment.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-04.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Tariq read about the scholars who traveled far and wide, sharing their knowledge across lands. They believed that learning was a light to be shared, not hidden away.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-05.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Inspired, Tariq felt a calling to revive this lost tradition. He gathered his friends and shared what he had learned, igniting their imaginations and dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-06.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Together, they decided to create their own Circle of Light, a place where they could gather to learn and share knowledge with others just like their ancestors.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-07.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'With the help of the community, they restored an old hall, transforming it into a center for learning. It soon became a beacon of inspiration for all who visited.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-08.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As the Circle of Light grew, people from nearby towns came to share their stories and wisdom. The tradition of knowledge sharing was alive once more.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-09.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Tariq’s heart swelled with joy as he saw the impact of their efforts. He knew they were honoring their heritage, creating a legacy for future generations.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-10.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'One evening, Tariq sat with his grandmother, recounting the success of the Circle of Light. Her eyes shone with pride, knowing the legacy of wisdom would endure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-11.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'As the stars twinkled in the night sky, Tariq felt a deep sense of connection to his roots. He understood that preserving their heritage was as important as the stories themselves.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-12.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'His grandmother’s gentle voice filled the air, "Never forget, Tariq, that knowledge is a light from Allah, meant to be shared and cherished by all."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-13.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'With a heart full of gratitude, Tariq knew he would carry this lesson with him wherever life led him, illuminating the path for others.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-14.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'As he drifted into sleep that night, Tariq dreamed of the many stories yet to be woven into the fabric of their shared heritage.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-15.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'His dreams carried him through lands of golden deserts and lush oases, where knowledge flowed like rivers, connecting generations of seekers.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-16.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'In his dreams, he saw the faces of those who came before him, guiding his steps and whispering the secrets of the past.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-17.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'Each morning, Tariq awoke with new determination, ready to embrace the day and continue the tradition of sharing and learning.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-18.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'The Circle of Light continued to thrive, a testament to the enduring power of knowledge and the bonds it created within the community.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-19.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'With each story shared and each lesson learned, the tradition of their ancestors lived on, a beacon of hope for future generations.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-20.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'Tariq often visited the library, now a dear friend, to discover new stories and add his own chapters to the ongoing legacy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-21.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'Through his journey, Tariq learned that honoring one’s roots means nurturing the seeds of knowledge and ensuring they blossom for all.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-22.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'And so, with love and dedication, Tariq and his friends carried the torch of knowledge forward, lighting the way for those who would come after.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-23.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'As the night gently embraced the city, Tariq knew that in every story told and every lesson shared, they were united in a tradition of light. Goodnight, young seekers.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/lost-tradition/page-24.webp' from public.stories where slug='lost-tradition' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Mender of Hearts', 'mender-of-hearts', 'young_explorers', '9-12', 'character_building', 'Quran 49:10', 'About reconciling between believers', 'forgiveness', 'An old wise woman helps enemies become friends again. Learn how forgiveness heals wounds and brings peace to troubled hearts.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a village nestled between lush green hills, there lived an old woman named Amira. Known as the Mender of Hearts, she had a gift for bringing peace where there was discord. Her gentle smile and wise words were a balm to many troubled souls.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-01.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, two neighbors, Hamza and Yusuf, quarreled over a small patch of land. Their heated words echoed through the village, causing everyone to worry. But Amira knew that even the deepest wounds could be healed with understanding and forgiveness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-02.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Amira invited both men to her humble home, offering them tea and shelter from the afternoon sun. With gentle persuasion, she asked them to share their perspectives. Slowly, they began to listen to each other’s stories, realizing the roots of their misunderstanding.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-03.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'As the sun began to set, painting the sky in hues of orange and pink, Amira spoke of the power of forgiveness. "Forgiveness," she said softly, "is like a gentle rain that washes away the dust of anger, leaving the heart clear and bright."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-04.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Inspired by her words, Hamza turned to Yusuf. "I am sorry for my harsh words," he said sincerely. Yusuf nodded, his heart lightening. "And I am sorry for not listening," he replied. Their exchange marked the beginning of a renewed friendship.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-05.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The village rejoiced at the news of their reconciliation. Amira’s heart was full, knowing peace had returned. Under a sky full of stars, she whispered a prayer of gratitude, her spirit content and at ease.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-06.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As Amira rested that night, she thought of how forgiveness mends not just hearts but communities. Her dreams were sweet, filled with visions of a world wrapped in the gentle embrace of peace and understanding.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-07.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The next morning, the village awoke to birdsong and a renewed sense of unity. Amira’s story had spread far and wide, a timeless reminder that forgiveness holds the power to heal and transform.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-08.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'And so, in the hearts of all who knew her, Amira remained the beloved Mender of Hearts, a beacon of hope and kindness. Her legacy lived on, teaching generations the beauty of forgiveness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-09.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'As the night enfolds the world in its gentle embrace, let us remember Amira’s tale. May our dreams be as sweet, and our hearts as light, knowing that forgiveness is always within reach.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mender-of-hearts/page-10.webp' from public.stories where slug='mender-of-hearts' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Merchant''s Choice', 'merchant-choice', 'young_explorers', '9-12', 'character_building', 'Quran 2:282', 'Verse about honesty in business transactions', 'honesty', 'A merchant faces temptation to deceive for profit. Watch as he chooses integrity and discovers it''s worth more than any treasure.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a bustling bazaar nestled between rolling hills, lived a wise and respected merchant named Tariq. Known for his vibrant stall filled with spices and textiles, Tariq always greeted his customers with a warm smile.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-01.webp' from public.stories where slug='merchant-choice' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, a rare spice came into Tariq''s possession. Its aroma was legendary, and its worth was equally high. As he prepared to sell it, a voice inside tempted him to raise the price beyond its value.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-02.webp' from public.stories where slug='merchant-choice' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'As Tariq pondered, he remembered the teachings of honesty from the Holy Quran. He knew that true success was not measured in gold but in trust and integrity. The decision weighed heavily on his heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-03.webp' from public.stories where slug='merchant-choice' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'With renewed clarity, Tariq decided to sell the spice at its correct value. His heart felt lighter, and as the day went on, customers thanked him for his fairness and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-04.webp' from public.stories where slug='merchant-choice' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'News of Tariq''s honesty spread throughout the town. People came from far and wide, eager to trade with a merchant they could trust. His reputation for fairness became his greatest treasure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-05.webp' from public.stories where slug='merchant-choice' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As the stars twinkled above the sleeping town, Tariq thanked Allah for guiding him. He knew that the wealth of the heart was far greater than any riches, and he drifted into a peaceful sleep.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/merchant-choice/page-06.webp' from public.stories where slug='merchant-choice' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Mirror of Truth', 'mirror-of-truth', 'young_explorers', '9-12', 'character_building', 'Quran 47:16', 'Reference to understanding and reflection', 'self-reflection', 'A young person looks in a magical mirror that shows truth. Through difficult reflections, they learn to accept themselves and grow.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in the vibrant village of Noorville, lived a curious young boy named Ameen. He was known for his adventurous spirit and unyielding quest for knowledge. One day, while exploring the attic of his grandfather''s house, Ameen stumbled upon a dusty, ornate mirror.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-01.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'The mirror shimmered mysteriously, drawing Ameen closer. As he brushed off the dust, he noticed an inscription along its golden frame. Intrigued, he whispered the words aloud, and suddenly, the mirror''s surface began to ripple like water.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-02.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'To his astonishment, the mirror spoke in a gentle, melodic voice, "I am the Mirror of Truth. I reveal what is within, not just what is seen. Are you ready for this journey, young one?" Ameen nodded bravely, his heart racing with excitement.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-03.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'The mirror showed Ameen various scenes from his life—times of joy, moments of kindness, and instances where he felt jealous or angry. Each scene lingered before fading into another, like pages turning in a storybook.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-04.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'One particular scene showed Ameen being unkind to a classmate. He felt a pang of guilt. The mirror''s voice gently reminded him, "Every soul makes mistakes, but the wise learn and grow from them." Ameen nodded, contemplating the lesson.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-05.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As the reflections continued, Ameen saw the support and love of his family and friends. He realized their significance and felt gratitude swell within him. He promised himself to cherish these relationships more deeply.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-06.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The mirror then showed a radiant silhouette, reminiscent of the stories of prophets Ameen had heard. It filled him with awe and a strong sense of peace, reminding him of the importance of guidance and wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-07.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Finally, the mirror quieted, its surface returning to normal. Ameen felt a profound sense of understanding. He realized that true reflection comes from looking within and accepting all parts of oneself with compassion.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-08.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As the sun set in vibrant hues of orange and pink, Ameen left the attic, carrying the lessons of the Mirror of Truth in his heart. He felt lighter, knowing that self-reflection was a journey worth taking.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-09.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'With newfound wisdom, Ameen approached his days differently, always mindful of his actions and thoughts. He learned to be kinder to himself and others, nurturing the seeds of growth and understanding.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-10.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'His reflection in the mirror came to symbolize a journey not just of sight, but of heart. Ameen understood that true beauty lay in the courage to change and the strength to grow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-11.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'As he fell asleep that night, Ameen remembered the gentle voice of the mirror. In his dreams, he continued to explore, guided by the light of understanding and the warmth of acceptance.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mirror-of-truth/page-12.webp' from public.stories where slug='mirror-of-truth' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Moon''s Friendship', 'moon-friendship', 'rising_moons', '6-8', 'daily_life', 'Quran 21:33', 'He created the night and the day, and the sun and the moon', 'kindness', 'The moon befriends the stars and learns what it means to shine together. A warm story about friendship and support.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in the velvety sky, the Moon felt a little lonely. It gazed down at the earth, admiring its beauty.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-01.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'The Moon noticed the stars twinkling around it. ''Hello, Stars!'' said the Moon. ''Will you be my friends?''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-02.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'The stars twinkled brighter in response. ''Of course, Moon! Together, we can light up the night sky!'' they chimed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-03.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'The Moon felt happy. It realized that with the stars, it wasn''t just a lonely glow but part of a beautiful, twinkling sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-04.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Every night, the Moon and stars danced together, creating a beautiful spectacle for the world below to see.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-05.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'People on Earth would look up and smile, feeling the kindness and friendship shining down on them.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-06.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The Moon, with its new friends, learned that shining together made the night even more beautiful.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-07.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Each night, the Moon and stars would bring joy and calm to the world, a testament to their luminous friendship.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-08.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'One night, a gentle breeze whispered, ''Thank you, dear Moon and stars, for your kindness and light.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-09.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The Moon smiled, knowing its friendship with the stars brought light and warmth to the night.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-10.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Stars whispered, ''Together, we are stronger. Together, we make the night beautiful.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-11.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'And so, every night, the Moon and stars continued to shine, spreading kindness from above.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-12.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Even when clouds would cover the moon, the stars twinkled brightly to keep the night aglow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-13.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The Moon felt grateful, understanding true friendship means supporting each other in all times.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-14.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'On clear nights, the Moon and stars would shine their brightest, a reminder of their enduring friendship.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-15.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, '''Thank you, Stars,'' the Moon whispered softly, ''for making every night a wondrous one.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-16.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The stars twinkled back, ''We’re glad to be your friends, dear Moon.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-17.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'The Moon and stars knew that together, their light reached far and wide, touching hearts everywhere.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-18.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'Every night, before the world slept, they would share a quiet moment, grateful for each other’s light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-19.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'And so, as the Earth turned, the Moon whispered to the stars, ''Goodnight, dear friends.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/moon-friendship/page-20.webp' from public.stories where slug='moon-friendship' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Mountain''s Humility', 'mountain-humility', 'young_explorers', '9-12', 'quran_inspired', 'Quran 48:26', 'Reference to mountains and their creation', 'humility', 'A tall mountain discovers that even the mightiest must humble themselves before Allah. A meditative story about strength and submission.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a land where the sun kissed the horizon each morning, there stood a mountain, tall and proud. It reached high, brushing the sky with its peaks. People from nearby villages marveled at its strength, and birds danced joyfully around its summit.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-01.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'From its heights, the mountain could see all around. It watched over fields of lush greens and rivers running like ribbons through the valleys. The mountain felt grand and invincible, cherished by the land it overlooked.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-02.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, a gentle breeze whispered through the cliffs, carrying stories of an even greater power—Allah, the Creator of all. The mountain listened, curious and intrigued by tales of divine might and wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-03.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Intrigued, the mountain remembered the Quranic verse that spoke of its creation, a reminder of submission to Allah''s will. It pondered its own existence and the purpose it served, realizing there was much to learn.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-04.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The mountain understood that despite its grandeur, it was but a humble part of a greater whole. It felt a deep sense of peace, knowing it was created with purpose by Allah, just like everything else around it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-05.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As the sun set, painting the sky with hues of orange and blue, the mountain whispered a prayer of gratitude. It was content, embracing its role within the divine order, and acknowledging the Creator''s infinite wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-06.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'With every dawn, the mountain now stood not just in strength, but in humility. It became a beacon of reflection for all who looked upon it, reminding them of the beauty in submission to Allah''s will.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-07.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'And so, the mountain lived, a silent testament to the balance of strength and humility. The villagers, inspired by its serenity, would visit often, feeling a sense of calm in its presence.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-08.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As stars began to twinkle like diamonds in the night sky, the mountain watched over the sleeping world, a gentle guardian. It was content, knowing it was part of something far greater than itself.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-09.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The mountain''s story reminds us all that true strength lies in humility and submission to Allah. It teaches us to embrace our roles, find peace in our existence, and acknowledge the greatness of our Creator.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-10.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As we close our eyes and drift into dreams, let us remember the mountain''s lesson. Like it, we can stand tall, grounded in faith and humility, and embrace the wondrous world Allah has created for us.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/mountain-humility/page-11.webp' from public.stories where slug='mountain-humility' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Night Star''s Secret', 'night-star-secret', 'little_stars', '3-5', 'daily_life', 'Quran 53:1', 'Surah An-Najm opens with the star', 'guidance', 'A lonely little star wonders if it matters. That night, it guides a lost traveler home and discovers its special purpose.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a sky full of stars, one little star felt alone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-01.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'The little star wondered, ''Do I really matter?''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-02.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'It watched other stars twinkling brightly and felt dim.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-03.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Down below, a traveler was lost in the dark.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-04.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The little star noticed the traveler and glowed brighter.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-05.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The traveler saw the bright star and followed its light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-06.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Step by step, the traveler found the right path home.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-07.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'At last, the traveler reached home, safe and sound.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-08.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The little star felt happy, knowing it had helped.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-09.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, '''I do matter,'' the little star realized with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-10.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'From then on, the little star shone with all its heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-11.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'It knew it had a special purpose in the sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-12.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Each night, it guided travelers with its glow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-13.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'And the little star felt loved by the One who made it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-14.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'As the night ended, it whispered, ''Goodnight, world.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-15.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'The world slept peacefully under the starry sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-star-secret/page-16.webp' from public.stories where slug='night-star-secret' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Night Visitor', 'night-visitor', 'young_explorers', '9-12', 'prophet_story', 'Quran 51:24-25', 'Story of Prophet Ibrahim''s guests', 'hospitality', 'A weary traveler arrives at night and is welcomed with open arms. This tale celebrates the Islamic virtue of generous hospitality.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the serene land of ancient times, under a vast sky filled with twinkling stars, there lived a kind and noble man named Prophet Ibrahim. His home was a humble place, nestled among rolling hills and lush fields.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-01.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One peaceful evening, as the sun dipped below the horizon, three travelers appeared on the path leading to his home. Their journey had been long, and their feet were weary from travel.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-02.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Prophet Ibrahim, always welcoming to guests, saw them approaching. He quickly rose to greet them, his heart filled with warmth and generosity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-03.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, '"Welcome, dear guests," he called out with a smile. "Please, come inside and rest. My home is your home tonight."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-04.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Inside, the house was filled with the comforting scent of freshly baked bread and spiced herbs. Prophet Ibrahim and his family hurried to prepare a meal for their unexpected visitors.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-05.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As the travelers settled, they felt the warmth of Ibrahim''s hospitality. They shared stories of their journey, and laughter filled the room, carrying with it a sense of peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-06.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Prophet Ibrahim knew these were not ordinary guests. There was something special about them, yet he asked for nothing in return for his kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-07.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The night grew deeper, and the stars shone even brighter above. The guests expressed their gratitude, feeling deeply moved by Ibrahim''s generosity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-08.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Before they departed, the travelers revealed themselves as messengers, bringing good news to Prophet Ibrahim. His heart swelled with joy and gratitude to Allah.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-09.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Their visit was a blessing, a gentle reminder of the beauty of giving without expecting in return. Ibrahim felt peaceful, his heart filled with faith.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-10.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As the travelers left, the night air was cool and refreshing. Ibrahim watched them disappear into the horizon, his heart content and full of love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-11.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Prophet Ibrahim returned to his home, feeling blessed and grateful. He knew that in giving, he had received something far greater.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-12.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'The stars began to fade as dawn approached, casting a gentle pink hue over the world. It was a new day, filled with hope and promise.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-13.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Prophet Ibrahim knew that hospitality was a gift, a way to share warmth and kindness with the world. And in that sharing, he found joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-14.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'His guests had come and gone, but the memory of their visit lingered, like a sweet fragrance carried on the breeze.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-15.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As the morning sun warmed the earth, Ibrahim felt a deep sense of contentment. His heart was full, knowing he had fulfilled his duty of kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-16.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The story of his guests became a cherished tale, a reminder to welcome all with open arms and a generous heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-17.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'Ibrahim''s tale was one of love and faith, teaching that true richness lies not in possessions but in the warmth we share with others.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-18.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'As night falls once more, the stars return to watch over the world, a reminder of the eternal beauty of kindness and faith.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-19.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'And so, dear children, as you drift into slumber, remember the gentle kindness of Prophet Ibrahim and the joy it brought to him and his guests.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-20.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'For kindness is a language understood by all, a bridge that connects hearts and spreads peace throughout the world.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-21.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'Let your heart be open, like Ibrahim''s, welcoming all with warmth and love. For in giving, we find true happiness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-22.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'As you close your eyes, remember the stars above. They guide your dreams, filled with the light of kindness and peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-23.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'Good night, dear one. May your dreams be sweet and your heart always kind. Until tomorrow, sleep well under the stars.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/night-visitor/page-24.webp' from public.stories where slug='night-visitor' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Otter''s Lesson', 'otter-lesson', 'little_stars', '3-5', 'daily_life', 'Islamic teachings on the importance of cleanliness (tahara)', 'Hadith about cleanliness as part of faith', 'discipline', 'A little otter learns the joy of being clean and fresh. A playful story about self-care and the importance of staying pure.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a lush green forest by a sparkling stream, lived a little otter named Omar.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-01.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Omar loved to play in the mud all day. He would roll around and giggle with his friends.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-02.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, his mother said, ''Omar, it''s time to wash up. Cleanliness is part of faith.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-03.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Omar didn''t want to stop playing, but he loved his mother. So, he waddled to the stream.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-04.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The water was cool and refreshing. Omar splashed and cleaned himself, feeling lighter.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-05.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As he washed, he noticed how his fur shone and smelled fresh like flowers.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-06.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'His friends joined him, and they played in the clean water, laughing happily.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-07.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'After they finished, they lay on the soft grass, feeling calm and content.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-08.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Omar realized how wonderful it felt to be clean. He smiled at his mother.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-09.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, '''Being clean is truly part of faith,'' Omar thought, feeling proud.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-10.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'From that day on, Omar washed every day, enjoying his clean fur.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-11.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'He loved how his fur shimmered in the sun, feeling fresh and happy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-12.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Mama Otter was proud. ''You are a clean and wonderful otter, Omar,'' she said.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-13.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Omar felt loved and happy with his clean fur and pure heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-14.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'He closed his eyes, ready to dream of more playful, clean days.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-15.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Goodnight, dear Omar. Sweet dreams until the sun rises again.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/otter-lesson/page-16.webp' from public.stories where slug='otter-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Patient Potter', 'patient-potter', 'young_explorers', '9-12', 'daily_life', 'Quran 64:3', 'He created you from a single soul', 'patience', 'A master potter shapes clay with patient hands. As his student learns the craft, she discovers how patience transforms raw material into beauty.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a quaint village, nestled between rolling hills, lived a master potter named Hassan. His hands, like magic, transformed clay into exquisite forms. People from far and wide admired his creations, each piece reflecting the serenity of his heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-01.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One bright morning, a young girl named Amina arrived at Hassan''s workshop. Her eyes sparkled with curiosity. ''Teach me, Master Hassan,'' she pleaded. Hassan smiled, seeing the eagerness in her gaze, and welcomed her into his world of clay.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-02.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Hassan guided Amina towards a lump of clay. ''First, we learn patience,'' he explained. Amina watched closely as Hassan''s hands moved gracefully, molding the clay with care and attention. She marveled at how the formless earth began to take shape.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-03.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Eager to try, Amina placed her hands on the clay. It wobbled and collapsed. Disheartened, she frowned. ''Patience, dear Amina,'' Hassan said gently. ''The clay will listen when you listen to its whispers.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-04.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'As days turned into weeks, Amina returned to the workshop, each day learning something new. Under Hassan''s watchful eye, her hands grew steadier, her heart calmer. Slowly, she began to understand the language of the clay.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-05.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'One evening, as the sun set in a blaze of colors, Amina finally shaped a pot that stood tall and proud. Her eyes shone with joy, seeing her hard work transformed into beauty. Hassan nodded approvingly, his own heart swelling with pride.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-06.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Amina realized the true lesson of patience. It was not just about waiting but growing, listening, and understanding. ''You have learned well, Amina,'' Hassan said, ''just as we are shaped from a single soul, so too does patience shape us.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-07.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'As the village lights began to twinkle like stars, Amina hugged Hassan. ''Thank you, Master Hassan,'' she whispered. The workshop, now quiet, felt like a place of magic where dreams took form, one patient step at a time.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-08.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Amina walked home under the starry sky, carrying her pot carefully. The evening air was cool and filled with the scent of jasmine. As she entered her home, her heart felt full of gratitude and peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-09.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'That night, as Amina lay in bed, she thought of the clay and the lessons it had taught her. She felt a sense of wonder at how patience could transform not only the clay but also herself.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-10.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'With a contented sigh, Amina closed her eyes. She imagined the clay whispering its secrets in her dreams, guiding her hands in a dance of creation. Sleep enveloped her like a warm, comforting blanket.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-11.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'In the gentle embrace of sleep, Amina knew she was blessed with the power of patience. A power that would help her shape her own future, as beautifully as she shaped the clay.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-12.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Thus, in the quiet of the night, the village lay still. But in Amina''s heart, a journey had just begun. A journey where patience would guide her, like a gentle light in the dark.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/patient-potter/page-13.webp' from public.stories where slug='patient-potter' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Prophet''s Smile', 'prophet-smile', 'little_stars', '3-5', 'prophet_story', 'Hadith: Abu Dharr reported the Prophet said ''Smiling at your brother is a charity''', 'Tirmidhi 1956 - Acts of kindness', 'kindness', 'A simple smile from a kind man transforms everyone''s day. Discover how small gestures of warmth create ripples of joy.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
