insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'He saw a child who was sad, and gave him a gentle smile.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-07.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The child''s face lit up, and he felt loved and happy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-08.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The child''s happiness spread to his friends and family.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-09.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Even the sun seemed to shine brighter, filling the day with warmth.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-10.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As the day ended, everyone felt the kindness in their hearts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-11.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The kind man''s smile had made the whole village happy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-12.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'As he walked home, the stars twinkled, as if smiling back.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/prophet-smile/page-13.webp' from public.stories where slug='prophet-smile' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
