insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Rainbow After the Rain', 'rainbow-after-rain', 'little_stars', '3-5', 'quran_inspired', 'Quran 94:5-6', 'Surah Al-Inshirah - verily with hardship comes ease', 'trust_in_allah', 'After a scary storm, little Zara learns that every difficulty brings something beautiful. A gentle story about finding hope and trust.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Little Zara loved to play outside. One day, the sky turned gray.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-01.webp' from public.stories where slug='rainbow-after-rain' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'The wind began to blow, and raindrops fell from the clouds.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-02.webp' from public.stories where slug='rainbow-after-rain' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Zara ran inside as the storm grew stronger.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-03.webp' from public.stories where slug='rainbow-after-rain' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'She watched the rain tap on the window, feeling a little scared.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-04.webp' from public.stories where slug='rainbow-after-rain' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Zara''s mom hugged her, saying, ''With every hardship, there comes ease.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-05.webp' from public.stories where slug='rainbow-after-rain' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Slowly, the rain stopped, and the sun peeked out.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rainbow-after-rain/page-06.webp' from public.stories where slug='rainbow-after-rain' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
