insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Rescued Gazelle', 'rescued-gazelle', 'rising_moons', '6-8', 'islamic_history', 'References to hunting practices and animal treatment in Islamic texts', 'Islamic teachings on compassion toward animals', 'compassion', 'A hunter''s son saves a gazelle from a trap. Watch as he learns that sometimes the noblest choice is to let the hunted go free.', 15, true, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a sunlit valley surrounded by lush trees and golden fields, young Omar walked beside his father, the hunter. His heart filled with curiosity about the world he was to explore.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-01.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, '"Look closely, Omar," his father said. "Hunting is not just about skill, but respect for Allah''s creatures." Omar nodded, eager to learn the lessons his father offered.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-02.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'As they walked, Omar heard a soft cry. He followed the sound and discovered a gazelle caught in a trap, its eyes wide with fear.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-03.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, '"Father! We must help," Omar pleaded. His father paused, understanding the compassion in his son’s heart. "Yes, my son. Helping those in need is a noble act."', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-04.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Gently, they freed the gazelle. It stood shakily, then leapt into the safety of the forest. Omar felt a warmth in his heart, knowing he had done a good deed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-05.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, '"Remember, Omar," his father said, "Kindness to animals is a sign of faith." Omar smiled, feeling the truth of his father''s words in his heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-06.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'As night fell, they returned home. Omar lay in bed, the memory of the gazelle''s freedom guiding him to peaceful dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/rescued-gazelle/page-07.webp' from public.stories where slug='rescued-gazelle' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The River''s Song', 'river-song', 'little_stars', '3-5', 'quran_inspired', 'Quran 47:15', 'Description of rivers in Paradise', 'peace', 'A gentle river flows and sings, bringing life and sustenance to all. A soothing bedtime tale about the beauty of flowing with purpose.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a land of dreams, a gentle river flowed. It sang a song of peace and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-01.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'The river sparkled under the warm sun, its waters clear and pure. It whispered secrets to the trees.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-02.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Birds fluttered above, chirping along. They loved the river’s song and felt happy and free.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-03.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'In the river lived fish, playful and swift. They enjoyed the cool, gentle currents.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-04.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Nearby, a little deer drank from the river. It felt calm and safe, knowing the river was a friend.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-05.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The river flowed past gardens filled with fruit. Trees offered their bounty with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-06.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'A kind farmer watered his plants with river water. Everything he grew was healthy and strong.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-07.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'As the river continued, it reached a meadow where children played and laughed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-08.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The river sang its gentle song, bringing joy and peace to everyone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-09.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'As night fell, the stars twinkled above. The river shimmered like silver.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-10.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Nearby, a wise owl watched from a tree. It listened to the river''s song, feeling at peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-11.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The river flowed with purpose, bringing life to all it touched. It never stopped.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-12.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Its song was a lullaby, soothing and warm. It reminded everyone of the beauty of peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-13.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'In their dreams, children saw the river. They felt loved and safe.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-14.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'The river''s song whispered goodnight, filling hearts with tranquility and joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-15.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Sleep now, little ones. The river will always sing, bringing peace to your dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/river-song/page-16.webp' from public.stories where slug='river-song' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Seed of Change', 'seed-of-change', 'rising_moons', '6-8', 'character_building', 'Quran 2:261', 'The parable of the seed bearing seven ears', 'patience', 'A child plants a tiny seed and waits. Watch as patience and small actions grow into something beautiful and meaningful.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once in a small village, Amira held a tiny seed in her palm. ''Plant it with care,'' her grandfather whispered with a gentle smile.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-01.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Amira dug a small hole in the earth and placed the seed inside. She covered it gently with soil and patted it down.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-02.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, '''Will it grow soon?'' Amira asked, eyes shining with wonder. Her grandfather nodded, ''With patience, you''ll see.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-03.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Each day, Amira watered the spot where the seed lay hidden. She waited and watched, her heart full of hope.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-04.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Weeks passed, and tiny green shoots began to peek through the soil. Amira clapped her hands with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-05.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'One morning, Amira saw seven tall stalks standing proudly. ''Look, grandfather!'' she exclaimed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-06.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, '''Just like the story of the seed bearing seven ears,'' her grandfather said, his voice filled with warmth.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-07.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Amira nodded, understanding that small actions, nurtured with patience, can lead to great beauty.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-08.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'The garden was alive with buzzing bees and fluttering butterflies, celebrating the new growth.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-09.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, '''Thank you, seed,'' Amira whispered, feeling grateful for the lesson in patience.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-10.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As the sun set in hues of orange and pink, Amira felt a warm peacefulness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-11.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The seed, once tiny and small, had grown into something beautiful, just like her patience.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-12.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Her grandfather smiled, ''Patience can turn the smallest seed into the greatest gift.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-13.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Amira felt proud of the seed and herself. She had learned the power of waiting and nurturing.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-14.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'The village children came to see the wonder Amira had grown. ''How did you do it?'' they asked.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-15.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, '''With patience and love,'' Amira replied, smiling brightly at her new friends.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-16.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The sun dipped below the horizon, and the garden whispered goodnight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-17.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'As stars began to twinkle, Amira felt a sense of calm, knowing she had nurtured more than just a seed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-18.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'She had grown her heart with patience, just like her grandfather had taught her.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-19.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'With a sleepy yawn, Amira whispered, ''Goodnight, garden,'' and drifted into sweet dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/seed-of-change/page-20.webp' from public.stories where slug='seed-of-change' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Shepherd and the Lost Lamb', 'shepherd-lost-lamb', 'rising_moons', '6-8', 'prophet_story', 'Quran 37:100-107', 'Story of Prophet Ibrahim and his devoted son', 'obedience', 'A shepherd searches tirelessly for his lost lamb. This tender story shows us the depth of responsibility and care in guiding those we love.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a lush valley surrounded by towering mountains, there lived a kind shepherd named Ibrahim. Every day, he took his flock of sheep to graze in the green pastures.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-01.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'One day, as the sun began to set, Ibrahim counted his sheep. To his surprise, he realized one little lamb was missing!', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-02.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Ibrahim felt a deep sense of responsibility. ''I must find the lost lamb,'' he said, his heart filled with determination and care.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-03.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'He asked his son, Ismail, to help. Ismail eagerly agreed, understanding the importance of their task.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-04.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Together, they searched the valley, calling out gently to the lamb. ''Oh little lamb, where are you?''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-05.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'They walked through fields and around the hills, listening carefully for any sound of their lost friend.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-06.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Finally, in a meadow filled with wildflowers, they heard a soft ''baa'' coming from a small bush.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-07.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Ismail approached the bush gently and found the little lamb, scared but unharmed.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-08.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, '''There you are!'' Ismail exclaimed, smiling. He carefully picked up the lamb and carried it back to Ibrahim.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-09.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Ibrahim felt grateful and proud. ''You did well, my son,'' he said, embracing Ismail with love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-10.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As they returned home, the stars began to twinkle in the sky, guiding them like gentle lanterns.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-11.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The entire flock, now complete, followed them back, peacefully nibbling on the grass.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-12.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Ibrahim and Ismail felt the warmth of the lesson learned: always care for those we are responsible for.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-13.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As they reached their home, the moon hung high, casting a gentle light over their little house.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-14.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Ibrahim tucked Ismail into bed, his eyes filled with love. ''Goodnight, my dear son,'' he whispered.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-15.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Ismail smiled, feeling safe and loved. ''Goodnight, Father,'' he replied, his heart full of peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-16.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'Outside, the night was calm, and the sheep settled in, knowing they were safe under Ibrahim''s care.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-17.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'The valley was quiet, wrapped in the peaceful embrace of the night, as if saying its own gentle goodnight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-18.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'Ibrahim sat outside for a moment, thanking Allah for the blessing of his family and the safe return of the lamb.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-19.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'And so, the night whispered a gentle promise of peace, cradling everyone in a warm, loving embrace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-lost-lamb/page-20.webp' from public.stories where slug='shepherd-lost-lamb' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Shepherd''s Promise', 'shepherd-promise', 'little_stars', '3-5', 'prophet_story', 'Quran 26:32-34', 'Prophet Musa''s early life tending sheep', 'responsibility', 'A young shepherd makes a promise to protect his flock. Through kindness and care, he learns what it means to be trustworthy.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, young Musa was a shepherd. He walked with his sheep every day.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-01.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'He promised to care for them, to keep them safe and happy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-02.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'The sheep loved him. They felt safe with Musa by their side.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-03.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Musa knew every sheep by name. He watched over them with love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-04.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'One day, a little lamb wandered away. Musa looked for him everywhere.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-05.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'He found the lamb stuck in a bush. Musa gently freed him.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-06.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'The lamb bleated happily, grateful to be safe again.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-07.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Musa smiled and promised to always watch over them.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-08.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Every day, Musa led his sheep with care. He was their friend and protector.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-09.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'He learned that being responsible meant being kind and gentle.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-10.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Musa loved his sheep. They were a part of his family.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-11.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'The sheep loved Musa too. They trusted him completely.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-12.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'A shepherd must always keep his promise, Musa learned with joy.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-13.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'He thanked Allah for his sheep and for teaching him responsibility.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-14.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Musa felt a warm happiness in his heart, knowing he was doing good.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-15.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As the stars twinkled, Musa whispered, ''Goodnight, dear sheep.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/shepherd-promise/page-16.webp' from public.stories where slug='shepherd-promise' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Silent Listener', 'silent-listener', 'young_explorers', '9-12', 'character_building', 'Quran 23:63', 'About those who listen and remember', 'wisdom', 'A boy who listens more than speaks learns the deepest secrets of the world. A thoughtful story about the power of attention.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the bustling village of Noor, where vibrant markets spill into winding alleys, there lived a boy named Umar. Unlike the other children, Umar chose silence over chatter. His wide, curious eyes often lingered on the people around him, soaking in their stories and dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-01.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Umar''s favorite spot was beneath the ancient olive tree at the heart of the village. Its branches whispered secrets of old to anyone willing to listen. Here, Umar would sit for hours, letting the gentle rustle of leaves fill his mind with tales from the past.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-02.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One evening, as the sun dipped below the horizon, a wise old traveler stopped by the village. His robes shimmered like the stars, and his voice carried the wisdom of distant lands. Umar listened intently as the traveler spoke of courage, kindness, and the mysteries of the universe.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-03.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'The traveler noticed Umar''s quiet attention. ''You have the gift of listening, young one,'' he said, ''and with it, you will unlock the deepest truths of the world.'' Umar''s heart swelled with a gentle warmth, feeling understood and appreciated.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-04.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The next day, Umar heard the village elders discussing a problem. Their voices were filled with worry, yet none noticed the quiet boy listening nearby. As they paused in frustration, Umar softly offered a solution he had heard once before.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-05.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'The elders looked at Umar with surprise and gratitude. His suggestion was both simple and wise, and it solved their problem with ease. From that day forward, they sought his insight, valuing his quiet wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-06.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Word of Umar''s wisdom spread throughout the village. Children began to gather around him beneath the olive tree, eager to hear the stories and lessons he had learned from listening.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-07.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'As the seasons changed, so did Umar. He grew not just in years, but in understanding. He realized that true wisdom came from the heart, and listening was the key to unlocking it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-08.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Years passed, and Umar became known as the silent sage of Noor. His gift of listening brought peace and harmony to the village, where everyone found a place to be heard.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-09.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'On a gentle night, with the stars softly twinkling above, Umar lay under the olive tree, feeling the soothing presence of the world around him. He smiled, knowing he had found his place in the universe.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/silent-listener/page-10.webp' from public.stories where slug='silent-listener' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Spider''s Lesson', 'spider-lesson', 'rising_moons', '6-8', 'quran_inspired', 'Quran 29:41', 'The parable of the spider''s web', 'reflection', 'A little spider weaves with care but learns an important lesson about strength and weakness. A thoughtful story about understanding ourselves.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a lush green forest, there lived a little spider named Sama. She was very excited because today she would weave her very first web.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-01.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Sama worked carefully, spinning her silk strand by strand. She imagined her web as the strongest and most beautiful in the whole forest.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-02.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Just then, a gentle breeze rustled through the trees, causing Sama’s web to sway lightly. She paused and took a deep breath, focusing again on her task.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-03.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'As the day passed, Sama’s web grew larger and more intricate. She felt proud and couldn''t wait to show it to her forest friends.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-04.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Suddenly, a strong gust of wind blew through the forest. To her surprise, Sama watched as her beautiful web wobbled and tore apart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-05.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Sama sighed but remembered a story her mother told her about the spider’s web in the Quran. It taught about strength and weakness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-06.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'She understood that while her web was fragile, it was also a part of her journey to learn and grow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-07.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'With newfound determination, Sama began weaving again, this time with a deeper understanding of her craft.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-08.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Her forest friends gathered around, watching with admiration as Sama worked with patience and care.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-09.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Sama finished her web just as the stars began to twinkle in the night sky. It was even more beautiful than before.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-10.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'As she rested in the center of her web, Sama knew she had learned something precious: strength is not always what it seems.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-11.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Her web might still be delicate, but her spirit felt strong and unbreakable.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-12.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'That night, Sama whispered a gentle prayer of gratitude and drifted off to sleep, surrounded by the quiet hum of the forest.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-13.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As Sama slept, a gentle breeze passed through the trees, but her new web held strong, swaying gently but staying intact.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-14.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'The stars above twinkled as if whispering secrets of the night, and Sama knew she was loved and guided.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-15.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'And as the night enveloped the forest, Sama’s heart felt light, knowing that she was a part of something much bigger.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-16.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'The next morning, Sama awoke to the soft light of dawn and a renewed sense of purpose.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-17.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'She greeted the new day with a smile, ready to embrace whatever came her way with grace and patience.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-18.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'She knew that strength came from within, and she was ready to share her newfound wisdom with the world.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-19.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'As the forest hummed with life, Sama felt at peace, her heart filled with warmth and love, ready to dream again.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/spider-lesson/page-20.webp' from public.stories where slug='spider-lesson' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Student''s Question', 'student-question', 'young_explorers', '9-12', 'daily_life', 'Quran 20:114', 'Ask for increase in knowledge', 'wisdom', 'A curious student asks questions others fear to ask. Through her journey, she learns that seeking knowledge and truth brings enlightenment.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of a bustling town, young Amina sat in her classroom, her eyes wide with wonder. Her teacher spoke of the stars, the oceans, and the mountains, and Amina''s hand shot up eagerly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-01.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Amina was known for her curiosity. While others whispered, ''Don''t ask such questions,'' Amina''s heart brimmed with a thirst for knowledge, inspired by the teachings of the Prophet.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-02.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One evening, as the sun dipped low, Amina approached her wise grandfather. ''Grandfather,'' she began, ''Why do the stars twinkle? What secrets do they hold?''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-03.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Her grandfather, a man with a gentle smile, replied, ''The stars remind us of Allah''s vast creation. They are signs for those who seek understanding.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-04.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, '''But never be afraid to ask, my dear,'' he continued. ''Allah loves those who seek knowledge, as the Quran guides us to pray for an increase in wisdom.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-05.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Inspired, Amina decided to explore more. She visited the library, a place filled with books about the world, history, and science.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-06.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Each book she read opened new worlds. She learned of ancient civilizations, of the wonders of nature, and the beauty of the Quran''s teachings.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-07.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Amina''s friends began to notice the spark in her eyes. ''Tell us what you learn,'' they asked, gathering around her at recess.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-08.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'She shared stories of explorers, inventors, and scholars who never stopped asking questions. Her friends listened, captivated by the wonders Amina described.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-09.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'One day, Amina''s teacher announced a contest for the best science project. Amina''s mind buzzed with ideas, from the stars to the seas.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-10.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'With her grandfather''s words in her heart, Amina decided to work on a project about the constellations and their stories.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-11.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'She researched diligently, visiting the library and asking her teacher for guidance. Her passion inspired others to join her quest for knowledge.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-12.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Finally, the day of the contest arrived. Amina stood confidently, her project neatly displayed, shining under the classroom lights.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-13.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'As she presented, she felt a sense of peace and purpose. She realized that the journey of learning was a reward in itself.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-14.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Afterward, her teacher praised her efforts. ''You have shown us the beauty of curiosity, Amina. Keep asking questions.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-15.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Amina smiled, knowing her journey was just beginning. Each question she asked opened new doors, leading to endless discoveries.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-16.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'That night, as Amina lay in bed, she whispered a prayer, ''Oh Allah, increase me in knowledge,'' feeling grateful for the gift of curiosity.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-17.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'Her heart was light, her mind was free, and her dreams were filled with the wonders she would explore tomorrow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-18.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'As sleep gently embraced her, Amina knew she was never alone. She carried within her the light of knowledge and the warmth of love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-19.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'For each question she asked was like a star in the sky, lighting her path and guiding her toward her dreams.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-20.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'Amina''s journey was just beginning, and with each new day, her heart would seek the knowledge that Allah had placed in this vast world.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-21.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'Her story was one of many, a reminder that wisdom and compassion could change the world, one curious mind at a time.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-22.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'The stars continued to twinkle in the sky, each one a reminder of Allah''s infinite creation and the endless journey of learning.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-23.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'As Amina drifted into sleep, she felt wrapped in a comforting embrace, knowing tomorrow held new adventures and endless questions.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/student-question/page-24.webp' from public.stories where slug='student-question' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Tent of Welcome', 'tent-of-welcome', 'rising_moons', '6-8', 'islamic_history', 'References to Bedouin hospitality in Islamic tradition', 'Islamic cultural emphasis on welcoming guests', 'hospitality', 'A family opens their tent to a stranger, not knowing he will change their lives. A beautiful story about generous hearts.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the heart of the desert, the golden sun set behind rolling dunes. A small Bedouin family prepared their evening meal, the scent of spices dancing in the warm air.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-01.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Ali, the youngest, watched as his father, Hamza, placed a beautiful woven rug at the entrance of their tent. ''Why do we always do this, Baba?'' Ali asked curiously.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-02.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, '''To welcome guests, my son,'' Hamza replied with a gentle smile. ''We treat guests like family, for they bring blessings to our home.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-03.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'As night fell, a stranger approached. His silhouette was bathed in the soft glow of the moon. Ali''s heart filled with wonder as Hamza welcomed him with open arms.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-04.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The stranger spoke with a voice like honey. ''I am in need of rest and shelter for the night,'' he said. Hamza nodded, ''Our home is yours.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-05.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Over a shared meal, laughter and stories filled the tent. Ali felt a special warmth in his heart, as if the desert itself was smiling.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-06.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Later, as Ali lay in his bed, he whispered to his father, ''I feel like we''ve known him forever.'' Hamza patted his son''s head gently, ''Kindness makes strangers into friends.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-07.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'The next morning, the stranger prepared to leave. ''Thank you for your hospitality,'' he said, his presence still filling the tent with light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-08.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'Before departing, he handed Hamza a small pouch. ''A gift for your kindness,'' he said. Inside were seeds of unknown plants, shimmering with potential.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-09.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Ali watched as the seeds were planted near the tent. ''What will they grow into?'' he wondered aloud. Hamza replied, ''With care, something wonderful.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-10.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Days turned into weeks, and the seeds sprouted into beautiful flowers never seen before in the desert. Their vibrant colors dazzled everyone who passed by.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-11.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Travelers stopped to admire the sight. The flowers seemed to whisper stories of kindness, drawing people from far and wide.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-12.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'Ali saw that their tent was never empty, filled with laughter and warmth. ''It''s as if the flowers invite the world to us,'' Ali said.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-13.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'One day, a wise traveler remarked, ''These flowers are a blessing, grown from seeds of kindness. Such is the reward of a generous heart.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-14.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Ali felt a deep sense of happiness. ''I understand now, Baba,'' he said. ''Our home is blessed because we open our hearts to everyone.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-15.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'That evening, the family gathered under the stars, surrounded by friends old and new. The desert night was filled with peace.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-16.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, '''Our story spreads like the seeds,'' Hamza said. ''Kindness grows and spreads, touching all it meets.'' Ali nodded, feeling proud and content.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-17.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'As Ali closed his eyes, he imagined the flowers waving goodnight. He felt the warmth of his family''s love, like a cozy blanket.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-18.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'In his dreams, Ali saw a world blooming with kindness, where every heart was as open as their family’s tent.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-19.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'With a heart full of peace, Ali whispered, ''Goodnight, world.'' And the gentle desert winds carried his wishes far and wide.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/tent-of-welcome/page-20.webp' from public.stories where slug='tent-of-welcome' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Traveler''s Thirst', 'traveler-thirst', 'rising_moons', '6-8', 'character_building', 'Hadith: Abu Huraira reported the Prophet said, ''Whoever gives a drink to a thirsty person''', 'Sunan Ibn Majah 4193 - Reward for giving water', 'generosity', 'A traveler is desperately thirsty when a child offers water. This simple act of kindness ripples through the community in unexpected ways.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the warmth of a golden afternoon, a lone traveler wandered through a small village. His throat was dry, and his steps were weary. He paused under a lush mango tree, hoping for relief.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-01.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Nearby, a young boy named Yusuf noticed the traveler. His heart filled with compassion. ''Are you thirsty, sir?'' he asked, holding up a small clay cup filled with water.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-02.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'The traveler smiled gratefully, accepting the water. ''Thank you, young one,'' he said, his voice now more vibrant. ''May Allah bless your kind heart.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-03.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'Yusuf''s simple act of kindness did not go unnoticed. Villagers who saw the exchange felt inspired. They began sharing what they could with others. Generosity spread like rays of the setting sun.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-04.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'In the evening, Yusuf''s father spoke to him. ''Your kindness has brought happiness to many today,'' he said. ''You are a beacon of light in our village.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-05.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As night fell, Yusuf lay in his bed, the stars twinkling like diamonds above. He felt a warmth in his heart, knowing he had made a difference.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-06.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, '''Thank you, Allah, for letting me help today,'' he whispered, closing his eyes. The night embraced him like a soft, comforting blanket.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-07.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'And so, the village slept under the care of the generous moon, wrapped in the warmth of kindness and dreams of a better tomorrow.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/traveler-thirst/page-08.webp' from public.stories where slug='traveler-thirst' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Twin Butterflies', 'twin-butterflies', 'little_stars', '3-5', 'daily_life', 'Quran 15:22', 'We send the winds to fertilize', 'unity', 'Two butterfly siblings stay together through their adventure. A sweet bedtime tale about the power of brotherly and sisterly love.', 10, true, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In a lush green meadow, two twin butterflies, Layla and Zayd, fluttered happily.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-01.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Layla and Zayd loved to dance with the gentle wind that whispered through the trees.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-02.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, the wind carried them far across the meadow to a new adventure.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-03.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'They saw a garden full of colorful blooms, each flower smiling up at them.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-04.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'The flowers welcomed them, offering sweet nectar to drink.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-05.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As they drank, they heard the flowers whisper, ''Thank you for visiting us.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-06.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Feeling happy, Layla and Zayd danced once more, their wings shimmering.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-07.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Together, they flew to a peaceful stream that glimmered in the sunlight.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-08.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'They rested by the stream, listening to the water''s gentle lullaby.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-09.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'The sun began to set, painting the sky in hues of orange and purple.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-10.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Layla said, ''Together, everything is an adventure, brother.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-11.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Zayd replied, ''Yes, sister, we are never alone.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-12.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'The stars began to twinkle above them, watching over their journey.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-13.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'The moon smiled gently, lighting their way back home.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-14.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'Layla and Zayd nestled into their cozy leaf bed, feeling safe and loved.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-15.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As they drifted to sleep, they dreamed of new adventures together.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/twin-butterflies/page-16.webp' from public.stories where slug='twin-butterflies' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Weaver''s Wisdom', 'weavers-wisdom', 'young_explorers', '9-12', 'daily_life', 'Quran 16:125', 'Call to wisdom and good counsel', 'wisdom', 'An old weaver teaches a young apprentice that every thread, even the dark ones, has its place in the pattern. A meditation on life''s complexity.', 20, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'In the quaint village of Noor, where the sun cast a warm golden light, lived an old weaver named Ustadh Hamza. His workshop was a haven of colors and textures, filled with rolls of vibrant threads.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-01.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Young Amin, wide-eyed with curiosity, had just begun as Ustadh Hamza''s apprentice. He marveled at the weaver’s skill, eager to learn the secrets of creating such beautiful patterns.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-02.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'One day, Amin noticed a spool of dark thread and asked, ''Why do you keep this dull color, Master?'' Ustadh Hamza smiled knowingly and beckoned him closer.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-03.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, '''Every thread has its place, my dear boy,'' Ustadh Hamza explained, as he began weaving. ''The dark threads are what give depth to the pattern, much like shadows give shape to the light.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-04.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Amin watched in awe as the tapestry grew, each thread finding its place, telling a story of harmony and contrast. He began to understand that without darkness, the light would not shine as brightly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-05.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'Weeks passed, and Amin practiced diligently. Under Ustadh Hamza''s patient guidance, he learned to weave patterns filled with life, wisdom, and balance.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-06.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'One afternoon, as the sun began to set, Ustadh Hamza shared a story. ''In life, Amin, we must call others with wisdom and good counsel, just as the Quran teaches us.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-07.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Amin nodded, understanding that his teacher was imparting a greater lesson. Every choice, every word, like every thread, must be chosen with care and respect.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-08.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'As night fell, Amin said goodnight to his teacher, feeling grateful for the day’s learning. He realized that wisdom was not just in weaving, but in every action and word.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-09.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Returning home, Amin glanced up at the starlit sky, feeling a sense of peace. He knew that just like the stars, wisdom would light his path, guiding him gently through life''s patterns.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-10.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'The next morning, Amin woke with renewed energy, ready to weave not just threads but wisdom into his life. He remembered Ustadh Hamza''s words: ''Call to wisdom and good counsel.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-11.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'With each new day, Amin practiced weaving with patience and care, integrating the lessons of life he had learned from his wise teacher and from the beautiful patterns he created.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-12.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'As time passed, Amin became known in Noor as a master weaver, revered not only for his skill but for the wisdom he shared through his work and words.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-13.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'One quiet evening, after a long day of weaving, Amin sat beneath his favorite tree, reflecting on the journey that had brought him wisdom and understanding.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-14.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'He realized that life, like a tapestry, is woven with moments of light and shadow, each one essential to crafting a complete and beautiful picture.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-15.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'As he listened to the gentle rustle of leaves, Amin whispered a quiet prayer of gratitude for the lessons learned and the wisdom shared by Ustadh Hamza.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-16.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'Feeling the cool breeze on his face, Amin smiled, comforted by the assurance that wisdom would always guide him, like a well-chosen thread in the tapestry of life.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-17.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'As the night deepened, Amin rose, feeling the embrace of the night air. He began his walk home, each step firm with the promise of a future woven with wisdom and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-18.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'His heart was filled with the gentle light of understanding, a gift from Ustadh Hamza, which he cherished deeply. It was a light that would never fade.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-19.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'Arriving home, Amin took one last look at the stars, feeling a profound connection to the world and its endless tapestry of life.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-20.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 21, 'As he settled into bed, Amin whispered a prayer, thanking Allah for the wisdom and guidance that had been woven into his life.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-21.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 22, 'With his heart full and mind at peace, Amin drifted off to sleep, embraced by the night and the quiet reassurance of a life well-lived.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-22.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 23, 'And so, as the stars watched over him, Amin dreamt of patterns yet to be woven, each one a testament to the power of wisdom and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-23.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 24, 'Goodnight, whispered the wind, carrying with it the essence of Ustadh Hamza’s lessons. In the quiet of the night, Amin was guided by the gentle threads of wisdom.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/weavers-wisdom/page-24.webp' from public.stories where slug='weavers-wisdom' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Well of Kindness', 'well-of-kindness', 'rising_moons', '6-8', 'prophet_story', 'Quran 12:36-40', 'Story of Prophet Yusuf and the well', 'forgiveness', 'A boy thrown into a well learns to forgive. Follow his journey as he discovers that letting go of anger brings freedom.', 15, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, there was a gentle boy named Yusuf. He had many brothers who, one day, decided to play a trick on him. They led him to a deep, mysterious well.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-01.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Yusuf looked around, confused, as he stood at the edge of the well. His brothers whispered and giggled, but he didn’t understand their plan.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-02.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'Suddenly, they pushed him gently, and he fell into the well. The darkness surrounded him, but he was not afraid. He knew he was not alone.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-03.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'In the well, Yusuf prayed to Allah. He believed that help would come, and his heart filled with patience and hope.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-04.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'One day, a passing caravan stopped for water. They found Yusuf and pulled him out. The traders were kind and took him on their journey.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-05.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'As the caravan traveled, Yusuf saw new lands and met many people. He never spoke of his brothers with anger, but instead with understanding.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-06.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, 'Yusuf’s heart grew warm with each new friend he made. He realized that holding onto anger would only weigh him down.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-07.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Years passed, and Yusuf became a wise and respected man. He never forgot what happened, but he forgave his brothers.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-08.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 9, 'One day, Yusuf’s brothers came to him, asking for help. They did not recognize the wise man he had become.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-09.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, 'Instead of being angry, Yusuf chose kindness. He revealed himself to his brothers and embraced them with open arms.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-10.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'His brothers were amazed by Yusuf’s forgiveness. They realized the strength in letting go of past mistakes.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-11.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 12, 'Yusuf taught them that forgiveness was like a gentle rain, washing away the sadness in their hearts.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-12.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 13, 'From that day on, Yusuf’s family was reunited. Love and peace filled their home, and they were never apart again.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-13.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 14, 'Every night, under the stars, Yusuf would tell his children about the power of forgiveness and kindness.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-14.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 15, 'His children learned that forgiving others brought them closer to Allah and made their hearts light.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-15.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 16, 'Yusuf felt grateful for his journey. He knew that kindness and forgiveness were gifts from Allah to be shared.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-16.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 17, 'As the years passed, Yusuf’s story became one of hope and inspiration for everyone who heard it.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-17.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 18, 'The well that once held him captive became a symbol of the strength found in forgiveness and love.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-18.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 19, 'And so, Yusuf lived a life full of joy, teaching everyone around him the beauty of a forgiving heart.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-19.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 20, 'As you drift to sleep, remember Yusuf’s tale. Let go of any anger, and let your heart be light. Goodnight, dear child.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/well-of-kindness/page-20.webp' from public.stories where slug='well-of-kindness' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.stories (title, slug, age_tier, age_range, category, source_reference, source_detail, theme, description, reading_time_minutes, is_free, cover_image_url) values ('The Whispering Wind', 'whispering-wind', 'little_stars', '3-5', 'quran_inspired', 'Quran 21:45', 'Reference to the wind carrying messages', 'wonder', 'The wind carries secrets and stories to those who listen. A dreamy bedtime tale about nature''s gentle messages.', 10, false, 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-00.webp') on conflict (slug) do update set title=excluded.title, is_free=excluded.is_free, cover_image_url=excluded.cover_image_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 1, 'Once upon a time, in a lush green meadow, a gentle wind began to whisper.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-01.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 2, 'Little Amal, with big curious eyes, listened closely. The wind had stories to tell.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-02.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 3, 'It spoke of faraway lands and twinkling stars in the night sky.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-03.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 4, 'The wind said, ''I carry messages from the leaves and the skies.''', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-04.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 5, 'Amal closed her eyes and felt the wonder of nature''s secrets.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-05.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 6, 'A butterfly landed on her hand, as if to share in the tales.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-06.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 7, '''Even the smallest creatures have stories,'' the wind whispered.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-07.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 8, 'Amal giggled, feeling the wind tickle her cheeks.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-08.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
