insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 10, '''Goodnight, little one,'' the wind sang softly.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-10.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
insert into public.story_pages (story_id, page_number, text_content, illustration_url) select id, 11, 'Amal waved goodbye to the wind, feeling peaceful and loved.', 'https://unlaqymnoapznqxeqgom.supabase.co/storage/v1/object/public/illustrations/whispering-wind/page-11.webp' from public.stories where slug='whispering-wind' on conflict (story_id, page_number) do update set text_content=excluded.text_content, illustration_url=excluded.illustration_url;
